  function initDatabase() {
    const savedMeetings = localStorage.getItem("echoaction_meetings");
    const savedActivities = localStorage.getItem("echoaction_activities");
    const savedSettings = localStorage.getItem("echoaction_settings");

    if (savedMeetings) {
      try { meetings = JSON.parse(savedMeetings); } catch(e) { console.warn("corrupted meetings", e); meetings = []; }
      window.meetings = meetings;
    (function(){ try { var st=document.createElement("style"); st.textContent='input[type=text],input[type=email],input[type=password],input[type=number],input[type=date],input[type=time],input[type=search],textarea,select{border:1px solid var(--accent-primary) !important;outline:none;}'; document.head.appendChild(st); } catch(e){} })();
    } else {
      // Load all mock meetings on first run
      meetings = [
        window.MeetingActionPlatform.mockMeetings[0],
        window.MeetingActionPlatform.mockMeetings[1],
        window.MeetingActionPlatform.mockMeetings[2]
      ];
      saveMeetingsToStorage();
    }
    if (!window.meetings) window.meetings = meetings;

    if (savedActivities) {
      try { activities = JSON.parse(savedActivities); } catch(e) { console.warn("corrupted activities", e); activities = []; }
    } else {
      activities = window.MeetingActionPlatform.devActivities;
      saveActivitiesToStorage();
    }

    if (savedSettings) {
      try { settings = JSON.parse(savedSettings); } catch(e) { console.warn("corrupted settings", e); }
    } else {
      localStorage.setItem("echoaction_settings", JSON.stringify(settings));
    }
  }

  function saveMeetingsToStorage() {
    localStorage.setItem("echoaction_meetings", JSON.stringify(meetings));
    window.meetings = meetings;
    if (currentUser) meetings.forEach(m => _dbSyncMeeting(m));
  }

  function saveActivitiesToStorage() {
    localStorage.setItem("echoaction_activities", JSON.stringify(activities));
    if (currentUser && activities.length > 0) _dbSyncActivity(activities[0]);
  }

  // --- DATE PARSING HELPERS ---
  function _parseDate(str) {
    if (!str) return null;
    if (typeof str !== "string") return null;
    // Try YYYY-MM-DD format
    const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) return new Date(parseInt(isoMatch[1]), parseInt(isoMatch[2])-1, parseInt(isoMatch[3]));
    // Try "Month Day, Year" format
    const natMatch = str.match(/^([A-Za-z]+)\s+(\d{1,2}),?\s*(\d{4})/);
    if (natMatch) {
      const months = {"january":0,"february":1,"march":2,"april":3,"may":4,"june":5,"july":6,"august":7,"september":8,"october":9,"november":10,"december":11};
      const m = months[natMatch[1].toLowerCase()];
      if (m !== undefined) return new Date(parseInt(natMatch[3]), m, parseInt(natMatch[2]));
    }
    // Try native Date parse as fallback
    const d = new Date(str);
    if (!isNaN(d.getTime())) return d;
    return null;
  }
  function _dateKey(d) {
    if (!d || isNaN(d.getTime())) return null;
    return `${d.getFullYear()}-${(d.getMonth()+1).toString().padStart(2,"0")}-${d.getDate().toString().padStart(2,"0")}`;
  }

  // --- MYSQL SYNC HELPERS ---
  function _csrfHeaders() {
    return { "Content-Type": "application/json", "X-CSRF-Token": _csrfToken };
  }
  async function _dbPost(url, body) {
    await ensureCsrfToken();
    try {
      const r = await fetch(url, { method: "POST", headers: _csrfHeaders(), body: JSON.stringify(body) });
      if (!r.ok && r.status !== 403) console.warn("DB sync error:", url, r.status);
    } catch(e) { console.warn("DB sync error:", url, e); }
  }
  function _dbSyncMeeting(m) { if (currentUser) _dbPost("/api/meetings", { meeting: m, email: currentUser.email }); }
  function _dbDeleteMeeting(id) {
    if (!currentUser) return;
    fetch("/api/meetings/" + id, {
      method: "DELETE",
      headers: _csrfHeaders(),
      body: JSON.stringify({ email: currentUser.email })
    }).catch(e => console.warn(e));
  }
  function _dbSyncActivity(a) { if (currentUser) _dbPost("/api/activities", { activity: a, email: currentUser.email }); }
  function _dbSyncSettings(s) { if (currentUser) _dbPost("/api/settings", { settings: s, email: currentUser.email }); }
  function _dbSyncUser(u) { _dbPost("/api/user", u); }
  function _dbSyncQuery(d) { _dbPost("/api/query", d); }
  function _dbSyncProfileLinks(links) { if (currentUser) _dbPost("/api/profile-links", { email: currentUser.email, links }); }
  function _dbSyncEditHistory(meetingId, field, oldVal, newVal, description) {
    if (currentUser) _dbPost("/api/edit-history", { meetingId, email: currentUser.email, field, oldValue: oldVal, newValue: newVal, description: description || "" });
  }
  function _dbLoadFromMySQL(email) {
    fetch("/api/meetings?email=" + encodeURIComponent(email))
      .then(r => r.json()).then(d => {
        if (d.success && d.meetings) {
          var localById = {};
          meetings.forEach(function(m) { localById[m.id] = m; });
          var merged = d.meetings.map(function(sm) { return localById[sm.id] || sm; });
          meetings.forEach(function(lm) { if (!merged.some(function(m) { return m.id === lm.id; })) merged.push(lm); });
          meetings = merged;
          localStorage.setItem("echoaction_meetings", JSON.stringify(meetings));
          window.meetings = meetings;
        }
        if (currentUser && currentUser.portal === "employee") {
          renderDashboardStats();
          renderDashboardFeed();
          renderDemoPicker();
          renderDashboardCalendar();
        }
        renderCalendar();
        if (typeof window._refreshNotifications === "function") window._refreshNotifications();
      }).catch(e => console.warn("load meetings:", e));
    fetch("/api/settings?email=" + encodeURIComponent(email))
      .then(r => r.json()).then(d => {
        if (d.success) { settings = d.settings; localStorage.setItem("echoaction_settings", JSON.stringify(settings)); }
      }).catch(e => console.warn("load settings:", e));
    fetch("/api/notifications?email=" + encodeURIComponent(email))
      .then(r => r.json()).then(d => {
        if (d.success && d.notifications.length > 0) {
          const badge = document.getElementById("notif-badge");
          const unread = d.notifications.filter(n => !n.isRead).length;
          if (badge && unread > 0) { badge.style.display = "flex"; badge.textContent = unread; }
          const list = document.getElementById("notifications-list");
          if (list) {
            list.innerHTML = "";
            d.notifications.slice(0, 10).forEach(n => {
              const div = document.createElement("div");
              div.style.cssText = "padding:0.6rem 1rem;border-bottom:1px solid var(--card-border);font-size:0.8rem;color:var(--text-secondary);";
              div.textContent = n.message;
              list.appendChild(div);
            });
          }
        }
      }).catch(e => console.warn("load notifications:", e));
  }
  function saveMeetingsToStorageLocal() {
    localStorage.setItem("echoaction_meetings", JSON.stringify(meetings));
    window.meetings = meetings;
  }

