  function updatePresetDropdownStyle(state) {
    const states = {
      default: {
        textColor: "var(--text-primary)",
        bgColor: "rgba(255, 255, 255, 0.05)",
        hoverText: "#ffffff",
        hoverBg: "rgba(99, 102, 241, 0.5)",
        selectedText: "#ffffff",
        selectedBg: "linear-gradient(to right, var(--accent-primary), rgba(99, 102, 241, 0.8))"
      },
      hover: {
        textColor: "var(--text-primary)",
        bgColor: "rgba(255, 255, 255, 0.07)",
        hoverText: "#ffffff",
        hoverBg: "rgba(99, 102, 241, 0.6)",
        selectedText: "#ffffff",
        selectedBg: "linear-gradient(to right, var(--accent-primary), rgba(99, 102, 241, 0.8))"
      },
      open: {
        textColor: "#f8fafc",
        bgColor: "rgba(15, 23, 42, 0.95)",
        hoverText: "#ffffff",
        hoverBg: "rgba(59, 130, 246, 0.7)",
        selectedText: "#ffffff",
        selectedBg: "rgba(37, 99, 235, 0.95)"
      },
      selected: {
        textColor: "#f8fafc",
        bgColor: "rgba(37, 99, 235, 0.85)",
        hoverText: "#ffffff",
        hoverBg: "rgba(37, 99, 235, 0.75)",
        selectedText: "#ffffff",
        selectedBg: "rgba(37, 99, 235, 0.95)"
      }
    };

    const config = states[state] || states.default;
    selectPresetActivity.style.color = config.textColor;
    selectPresetActivity.style.backgroundColor = config.bgColor;
    selectPresetActivity.style.setProperty("--select-option-text", config.textColor);
    selectPresetActivity.style.setProperty("--select-option-bg", config.bgColor);
    selectPresetActivity.style.setProperty("--select-option-hover-text", config.hoverText);
    selectPresetActivity.style.setProperty("--select-option-hover-bg", config.hoverBg);
    selectPresetActivity.style.setProperty("--select-option-selected-text", config.selectedText);
    selectPresetActivity.style.setProperty("--select-option-selected-bg", config.selectedBg);
  }

  if (selectPresetActivity) {
    selectPresetActivity.addEventListener("mouseenter", () => updatePresetDropdownStyle("hover"));
    selectPresetActivity.addEventListener("mouseleave", () => updatePresetDropdownStyle("default"));
    selectPresetActivity.addEventListener("focus", () => updatePresetDropdownStyle("open"));
    selectPresetActivity.addEventListener("blur", () => updatePresetDropdownStyle("default"));
    selectPresetActivity.addEventListener("click", () => updatePresetDropdownStyle("open"));
    selectPresetActivity.addEventListener("change", () => {
      updatePresetDropdownStyle("selected");
      Array.from(selectPresetActivity.options).forEach(option => {
        if (option.selected && option.value) {
          option.style.color = "#ffffff";
          option.style.backgroundColor = "rgba(37, 99, 235, 0.95)";
        } else {
          option.style.color = "var(--text-primary)";
          option.style.backgroundColor = "var(--bg-secondary)";
        }
      });
    });
    updatePresetDropdownStyle("default");
  }

