  // --- SIDEBAR COLLAPSE & MOBILE MENU ---
  function toggleSidebar() {
    appSidebar.classList.toggle("collapsed");
    const icons = document.querySelectorAll("#sidebar-collapse-btn i, #sidebar-collapse-inside i");
    icons.forEach(icon => {
      icon.className = appSidebar.classList.contains("collapsed") ? "fa-solid fa-angles-right" : "fa-solid fa-angles-left";
    });
  }
  const sidebarCollapseBtn = document.getElementById("sidebar-collapse-btn");
  const sidebarCollapseInside = document.getElementById("sidebar-collapse-inside");
  const appSidebar = document.getElementById("app-sidebar");
  const mobileMenuToggle = document.getElementById("mobile-menu-toggle");

  // Direct handlers
  if (sidebarCollapseBtn && appSidebar) {
    sidebarCollapseBtn.addEventListener("click", toggleSidebar);
    sidebarCollapseBtn.addEventListener("click", function(e) { e.stopPropagation(); });
  }
  if (sidebarCollapseInside && appSidebar) {
    sidebarCollapseInside.addEventListener("click", toggleSidebar);
    sidebarCollapseInside.addEventListener("click", function(e) { e.stopPropagation(); });
  }
  // Backup: delegated listener in case elements aren't found at init
  if (appSidebar) {
    appSidebar.addEventListener("click", function(e) {
      const t = e.target.closest("#sidebar-collapse-btn, #sidebar-collapse-inside");
      if (t) toggleSidebar();
    });
  }

  var sidebarBackdrop = document.getElementById("sidebar-backdrop");

  function openMobileSidebar() {
    appSidebar.classList.add("mobile-open");
    if (mobileMenuToggle) mobileMenuToggle.querySelector("i").className = "fa-solid fa-xmark";
    if (sidebarBackdrop) sidebarBackdrop.classList.add("active");
    var navScroll = document.querySelector(".sidebar .nav-menu");
    if (navScroll) {
      navScroll.scrollTop = 0;
      setTimeout(function(){ navScroll.scrollTop = 0; }, 400);
    }
  }
  function closeMobileSidebar() {
    appSidebar.classList.remove("mobile-open");
    if (mobileMenuToggle) mobileMenuToggle.querySelector("i").className = "fa-solid fa-bars";
    if (sidebarBackdrop) sidebarBackdrop.classList.remove("active");
    var navScroll = document.querySelector(".sidebar .nav-menu");
    if (navScroll) navScroll.scrollTop = 0;
  }

  if (mobileMenuToggle && appSidebar) {
    mobileMenuToggle.addEventListener("click", function() {
      if (appSidebar.classList.contains("mobile-open")) {
        closeMobileSidebar();
      } else {
        openMobileSidebar();
      }
    });
  }

  // Close sidebar via backdrop click
  if (sidebarBackdrop) {
    sidebarBackdrop.addEventListener("click", closeMobileSidebar);
  }

  // Close sidebar via close button inside sidebar
  var sidebarCloseBtn = document.getElementById("sidebar-mobile-close");
  if (sidebarCloseBtn) {
    sidebarCloseBtn.addEventListener("click", closeMobileSidebar);
  }

