  window.showToast = function showToast(message, type = "success") {
    const container = document.getElementById("toast-container");
    if (!container) return;
    const toast = document.createElement("div");
    toast.className = `toast ${type === "error" ? "error" : ""}`;
    
    const icon = type === "success" ? "fa-circle-check" : "fa-triangle-exclamation";
    const color = type === "success" ? "var(--success)" : "var(--danger)";
    toast.innerHTML = `
      <i class="fa-solid ${icon}" style="color: ${color}"></i>
      <span>${message}</span>
    `;
    toast.style.borderLeft = `4px solid ${color}`;
    toast.style.background = type === "success"
      ? "linear-gradient(135deg, rgba(16,185,129,0.12) 0%, rgba(17,24,39,0.95) 50%)"
      : "linear-gradient(135deg, rgba(239,68,68,0.12) 0%, rgba(17,24,39,0.95) 50%)";

    container.appendChild(toast);

    setTimeout(() => {
      toast.style.animation = "slideOut 0.25s ease forwards";
      setTimeout(() => toast.remove(), 300);
    }, 6000);
  }

