  // --- HELPER FORMATTING ---
  function formatTime(seconds) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  }

  // --- DASHBOARD: STATS ---
  function renderDashboardStats() {
    statTotalMeetings.textContent = meetings.length;

    let allTasks = [];
    meetings.forEach(m => { allTasks = allTasks.concat(m.actionItems || []); });

    const completed = allTasks.filter(t => t.status === "Completed").length;
    const total = allTasks.length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    statTaskCompletion.textContent = `${completionRate}%`;
    statPendingTasks.textContent = allTasks.filter(t => t.status !== "Completed").length;

    // Animate stat rings
    const maxMeetings = Math.max(meetings.length, 10);
    const ringMeetings = document.getElementById("ring-meetings");
    const ringTasks = document.getElementById("ring-tasks");
    const ringPending = document.getElementById("ring-pending");
    const ringFollowers = document.getElementById("ring-followers");

    function animateRing(el, pct) {
      if (!el) return;
      const circle = el.querySelector(".ring-progress");
      if (!circle) return;
      const circumference = 100.5;
      const offset = circumference - (circumference * Math.min(pct, 100)) / 100;
      setTimeout(() => { circle.style.strokeDashoffset = offset; }, 100);
    }

    animateRing(ringMeetings, (meetings.length / maxMeetings) * 100);
    animateRing(ringTasks, completionRate);
    animateRing(ringPending, total > 0 ? (allTasks.filter(t => t.status !== "Completed").length / total) * 100 : 0);
    const followerCount = currentUser && currentUser.followers ? currentUser.followers.length : 0;
    animateRing(ringFollowers, Math.min(followerCount * 10, 100));
    const followerStat = document.getElementById("stat-followers");
    if (followerStat) followerStat.textContent = followerCount;

    // Week meetings count
    const weekMeetings = document.getElementById("stat-week-meetings");
    const completedTasks = document.getElementById("stat-completed-tasks");
    if (weekMeetings) weekMeetings.textContent = meetings.length;
    if (completedTasks) completedTasks.textContent = completed;

    renderDashboardTrend();
    renderRecentMeetings();
  }

  // --- DASHBOARD: MINI CALENDAR ---
  let dashCalYear, dashCalMonth;
  function renderDashboardCalendar() {
    const now = new Date();
    if (dashCalYear === undefined) dashCalYear = now.getFullYear();
    if (dashCalMonth === undefined) dashCalMonth = now.getMonth();
    const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    const label = document.getElementById("dash-cal-month");
    const grid = document.getElementById("dashboard-calendar-days");
    if (!label || !grid) return;
    label.textContent = monthNames[dashCalMonth] + " " + dashCalYear;
    grid.innerHTML = "";
    const firstDay = new Date(dashCalYear, dashCalMonth, 1).getDay();
    const daysInMonth = new Date(dashCalYear, dashCalMonth + 1, 0).getDate();
    const today = new Date();

    // Build set of dates that have meetings for dot indicators
    const meetingDateKeys = new Set();
    (meetings || []).forEach(meet => {
      if (meet.date) {
        const mDate = _parseDate(meet.date);
        if (mDate) {
          const key = `${mDate.getFullYear()}-${mDate.getMonth()}-${mDate.getDate()}`;
          meetingDateKeys.add(key);
        }
      }
    });

    for (let i = 0; i < firstDay; i++) {
      const empty = document.createElement("div");
      empty.style.cssText = "width:100%;aspect-ratio:1;";
      grid.appendChild(empty);
    }
    for (let d = 1; d <= daysInMonth; d++) {
      const cell = document.createElement("div");
      const isToday = d === today.getDate() && dashCalMonth === today.getMonth() && dashCalYear === today.getFullYear();
      const dayKey = `${dashCalYear}-${dashCalMonth}-${d}`;
      const hasMeeting = meetingDateKeys.has(dayKey);
      cell.style.cssText = "position:relative;width:100%;aspect-ratio:1;display:flex;align-items:center;justify-content:center;border-radius:4px;font-size:0.6rem;cursor:pointer;transition:all 0.15s;" + (isToday ? "background:var(--accent-primary);color:#fff;font-weight:700;" : "color:var(--text-secondary);");
      cell.textContent = d;
      if (hasMeeting && !isToday) {
        const dot = document.createElement("span");
        dot.style.cssText = "position:absolute;bottom:1px;left:50%;transform:translateX(-50%);width:3px;height:3px;border-radius:50%;background:var(--accent-primary);";
        cell.appendChild(dot);
      }
      cell.addEventListener("click", () => { switchScreen("screen-calendar"); });
      grid.appendChild(cell);
    }
    const prevBtn = document.getElementById("dash-cal-prev");
    const nextBtn = document.getElementById("dash-cal-next");
    if (prevBtn) prevBtn.onclick = () => { dashCalMonth--; if (dashCalMonth < 0) { dashCalMonth = 11; dashCalYear--; } renderDashboardCalendar(); };
    if (nextBtn) nextBtn.onclick = () => { dashCalMonth++; if (dashCalMonth > 11) { dashCalMonth = 0; dashCalYear++; } renderDashboardCalendar(); };
  }

  // --- DASHBOARD: TREND CHART ---
  let dashTrendRange = 7;
  function renderDashboardTrend() {
    const chartEl = document.getElementById("dash-trend-chart");
    const labelsEl = document.getElementById("dash-trend-labels");
    if (!chartEl || !labelsEl) return;
    chartEl.innerHTML = "";
    labelsEl.innerHTML = "";

    const days = dashTrendRange;
    const now = new Date();
    const dayNames = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
    const data = [];

    for (let i = days - 1; i >= 0; i--) {
      const d = new Date(now);
      d.setDate(d.getDate() - i);
      const dateKey = `${d.getFullYear()}-${(d.getMonth()+1).toString().padStart(2,"0")}-${d.getDate().toString().padStart(2,"0")}`;
      const count = meetings.filter(m => {
        if (!m.date) return false;
        try { const md = new Date(m.date); return md.getFullYear()===d.getFullYear() && md.getMonth()===d.getMonth() && md.getDate()===d.getDate(); } catch(e) { return false; }
      }).length;
      data.push({ day: dayNames[d.getDay()], count });
    }

    const maxVal = Math.max(...data.map(d => d.count), 1);
    const barColors = ["var(--accent-primary)", "var(--accent-secondary)", "#a78bfa", "var(--success)", "#f43f5e"];

    data.forEach((item, i) => {
      const bar = document.createElement("div");
      const heightPct = (item.count / maxVal) * 100;
      const color = barColors[i % barColors.length];
      bar.style.cssText = `flex:1;min-width:0;height:${Math.max(heightPct, 4)}%;background:${color};border-radius:4px 4px 0 0;transition:height 0.6s cubic-bezier(0.34,1.56,0.64,1);opacity:0.85;cursor:pointer;position:relative;`;
      bar.title = `${item.day}: ${item.count} meeting(s)`;
      bar.addEventListener("mouseenter", () => { bar.style.opacity = "1"; bar.style.transform = "scaleY(1.05)"; bar.style.transformOrigin = "bottom"; });
      bar.addEventListener("mouseleave", () => { bar.style.opacity = "0.85"; bar.style.transform = "scaleY(1)"; });
      chartEl.appendChild(bar);

      const label = document.createElement("div");
      label.style.cssText = "flex:1;text-align:center;font-size:0.55rem;";
      label.textContent = item.day;
      labelsEl.appendChild(label);
    });

    // Trend button handlers
    document.querySelectorAll(".dash-trend-btn").forEach(btn => {
      btn.onclick = () => {
        document.querySelectorAll(".dash-trend-btn").forEach(b => {
          b.style.background = "transparent";
          b.style.color = "var(--text-muted)";
          b.classList.remove("active");
        });
        btn.style.background = "rgba(99,102,241,0.1)";
        btn.style.color = "var(--accent-primary)";
        btn.classList.add("active");
        dashTrendRange = parseInt(btn.getAttribute("data-range"));
        renderDashboardTrend();
      };
    });
  }

  // --- DASHBOARD: RECENT MEETINGS ---
  function renderRecentMeetings() {
    const container = document.getElementById("dash-recent-meetings");
    if (!container) return;
    container.innerHTML = "";

    const recent = [...meetings].sort((a, b) => {
      try { return new Date(b.date) - new Date(a.date); } catch(e) { return 0; }
    }).slice(0, 5);

    if (recent.length === 0) {
      container.innerHTML = '<div style="text-align:center;padding:1rem;color:var(--text-muted);font-size:0.8rem;">No meetings yet</div>';
      return;
    }

    recent.forEach(m => {
      const card = document.createElement("div");
      card.style.cssText = "display:flex;align-items:center;gap:0.6rem;padding:0.6rem 0.75rem;background:rgba(255,255,255,0.02);border:1px solid var(--card-border);border-radius:10px;cursor:pointer;transition:all 0.2s;";
      const iconBg = m.modeType === "video" ? "rgba(244,63,94,0.1)" : "rgba(99,102,241,0.1)";
      const iconColor = m.modeType === "video" ? "#f43f5e" : "var(--accent-primary)";
      const iconFA = m.modeType === "video" ? "fa-film" : "fa-microphone";
      const isClass = m.category === "Lecture Sync" || m.class_notes;
      const showClassBadge = isClass && currentUser && currentUser.portal !== "employee";
      card.innerHTML = `
        <div style="width:34px;height:34px;border-radius:8px;background:${iconBg};display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid ${iconFA}" style="font-size:0.8rem;color:${iconColor};"></i></div>
        <div style="flex:1;min-width:0;">
          <div style="font-weight:600;font-size:0.8rem;color:var(--text-primary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${m.title}</div>
          <div style="font-size:0.65rem;color:var(--text-muted);">${m.category || "General"} ${showClassBadge ? '&middot; Class' : ''}</div>
        </div>
        <div style="font-size:0.6rem;color:var(--text-muted);white-space:nowrap;">${m.date || ""}</div>
      `;
      card.addEventListener("mouseenter", () => { card.style.background = "rgba(99,102,241,0.05)"; card.style.borderColor = "rgba(99,102,241,0.2)"; });
      card.addEventListener("mouseleave", () => { card.style.background = "rgba(255,255,255,0.02)"; card.style.borderColor = "var(--card-border)"; });
      card.addEventListener("click", () => openMeetingDetails(m.id));
      container.appendChild(card);
    });
  }

  // --- DASHBOARD: QUICK ACTION CARDS ---
  function initDashQuickActions() {
    const viewAllBtn = document.getElementById("dash-view-all-meetings");
    if (viewAllBtn) viewAllBtn.addEventListener("click", () => { switchScreen("screen-meetings"); });

    // Hover effect on all action cards
    document.querySelectorAll(".dash-action-card").forEach(card => {
      card.addEventListener("mouseenter", () => { card.style.background = "rgba(99,102,241,0.06)"; card.style.borderColor = "rgba(99,102,241,0.3)"; card.style.transform = "translateY(-2px)"; });
      card.addEventListener("mouseleave", () => { card.style.background = ""; card.style.borderColor = "var(--card-border)"; card.style.transform = "translateY(0)"; });
    });
  }

  // --- DASHBOARD: MOCK DEMO MEETINGS ---
  function renderDemoPicker() {
    demoGrid.innerHTML = "";
    const mockDb = window.MeetingActionPlatform.mockMeetings;
    
    mockDb.forEach(meet => {
      const isAlreadyAdded = meetings.some(m => m.id === meet.id);
      
      const card = document.createElement("div");
      card.className = "demo-card";
      card.style.opacity = isAlreadyAdded ? "0.6" : "1";
      card.innerHTML = `
        <div class="demo-card-title">${meet.title}</div>
        <div class="demo-card-meta">
          <span><i class="fa-solid fa-layer-group"></i> ${meet.category}</span>
          <span>${isAlreadyAdded ? '<i class="fa-solid fa-circle-check" style="color: var(--success)"></i> Parsed' : '<i class="fa-solid fa-circle-play"></i> Process'}</span>
        </div>
      `;

      card.addEventListener("click", () => {
        if (isAlreadyAdded) {
          showToast("Meeting already exists in Hub. Opening it now...", "success");
          openMeetingDetails(meet.id);
          return;
        }
        triggerAIPipeline(meet);
      });

      demoGrid.appendChild(card);
    });
  }

  // --- DASHBOARD: PROCESSING PIPELINE SIMULATION & REAL API NODE ---
  function triggerAIPipeline(meetingData, isReal = false, file = null) {
    // Hide upload zone and picker, show progress
    uploadZone.style.display = "none";
    document.querySelector(".demo-picker-section").style.display = "none";
    processingVisualizer.style.display = "flex";

    let progress = 0;
    progressBar.style.width = "0%";

    if (!isReal) {
      // Mock simulator behavior
      const interval = setInterval(() => {
        progress += 2;
        progressBar.style.width = `${progress}%`;

        if (progress < 40) {
          processingTitle.textContent = "Demo Mode: Simulating audio transcription...";
          processingStatus.textContent = `Using placeholder transcript data for ${meetingData?.title || 'Demo Meeting'}...`;
        } else if (progress < 50) {
          processingTitle.textContent = "Demo Mode: Formatting transcripts...";
          processingStatus.textContent = "Generating a sample summary and action plan...";
        } else if (progress < 75) {
          processingTitle.textContent = "Demo Mode: Indexing content...";
          processingStatus.textContent = "Preparing the meeting summary and concise action items...";
        } else if (progress < 90) {
          processingTitle.textContent = "Demo Mode: Extracting tasks...";
          processingStatus.textContent = "Simulating task owners, deadlines, and Jira tickets...";
        } else if (progress < 100) {
          processingTitle.textContent = "Demo Mode: Finalizing summary...";
          processingStatus.textContent = "Writing a placeholder email draft and finishing the meeting card...";
        } else {
          clearInterval(interval);
          
          // Add meeting to database
          meetings.push(meetingData);
          saveMeetingsToStorage();
          logEdit("meeting_add", `Loaded demo meeting "${meetingData.title}"`);

          // Show Toast
          showToast(`AI Pipeline complete. Processed "${meetingData.title}"!`);

          // Reset display state
          setTimeout(() => {
            processingVisualizer.style.display = "none";
            uploadZone.style.display = "flex";
            document.querySelector(".demo-picker-section").style.display = "block";
            
            // Render dashboard updates
            renderDashboardStats();
            renderDemoPicker();

            // Open meeting in hub
            openMeetingDetails(meetingData.id);
          }, 800);
        }
      }, 80);
    } else {
      // Real API execution mode!
      let progressVal = 0;
      progressBar.style.width = "0%";
      const isGemini = getApiKeyType(settings.apiKey) === "gemini";

      if (isGemini) {
        processingTitle.textContent = "Gemini Processing Audio...";
        processingStatus.textContent = "Uploading audio payload directly to Gemini 1.5 Flash...";
      } else {
        processingTitle.textContent = "Whisper Transcribing Audio...";
        processingStatus.textContent = "Uploading audio payload to OpenAI Whisper node...";
      }

      // Animate progress up to 45% while Whisper runs
      const audioProgressInterval = setInterval(() => {
        if (progressVal < 45) {
          progressVal += 1;
          progressBar.style.width = `${progressVal}%`;
        }
      }, 150);

      (async () => {
        try {
          let aiResult = null;
          let rawText = "";

          if (isGemini) {
            // 1. Single call to Gemini for transcription and analysis
            aiResult = await generateMeetingDetailsWithGemini(file, settings.apiKey);
            clearInterval(audioProgressInterval);
            progressVal = 75;
            progressBar.style.width = "75%";
            
            // Reconstruct raw transcript text if possible
            rawText = aiResult.transcript ? aiResult.transcript.map(t => `${t.speaker}: ${t.text}`).join("\n") : "Audio processed successfully.";
          } else {
            // OpenAI flow:
            // 1. Transcribe audio
            rawText = await transcribeRealAudio(file, settings.apiKey);
            clearInterval(audioProgressInterval);
            progressVal = 45;
            progressBar.style.width = "45%";
            
            // 2. Generation phase
            processingTitle.textContent = "Llama Indexing Context...";
            processingStatus.textContent = "Analyzing speech signatures and drafting executive summary...";
            
            const gptInterval = setInterval(() => {
              if (progressVal < 85) {
                progressVal += 1;
                progressBar.style.width = `${progressVal}%`;
              }
            }, 200);

            aiResult = await generateMeetingDetails(rawText, settings.apiKey);
            clearInterval(gptInterval);
            progressVal = 85;
            progressBar.style.width = "85%";
          }

          // 3. Formatting and clean up phase
          processingTitle.textContent = "Extracting Jira & Action Items...";
          processingStatus.textContent = "Synthesizing tasks, assignees, deadlines, and Jira descriptors...";

          // Extract audio duration
          const durationSecs = await getAudioDuration(file);
          const formattedDuration = formatTime(durationSecs) + "s"; // e.g. "02m 45s"
          
          // Map AI result to premium structure
          const meetingId = "meet-rand-" + Date.now();
          const isVideoFile = (file && file.type && file.type.startsWith("video")) || currentFileType === "video";
          const cleanMeeting = {
            id: meetingId,
            title: aiResult.title || `Audio Sync [File: ${file.name}]`,
            category: aiResult.category || "General",
            date: new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" }),
            duration: formattedDuration,
            attendees: aiResult.attendees || ["Sarah Jenkins", "Marcus (Frontend)"],
            audioUrl: URL.createObjectURL(file),
            audioFile: file,
            modeType: isVideoFile ? "video" : "audio",
            fileType: isVideoFile ? "video" : "audio",
            summary: {
              overview: aiResult.summary?.overview || "No overview provided.",
              keyPoints: aiResult.summary?.keyPoints || [],
              sentiment: aiResult.summary?.sentiment || "Neutral",
              meetingScore: aiResult.summary?.meetingScore || 85
            },
            actionItems: (aiResult.actionItems || []).map((ai, index) => {
              const tm = resolveTeamMember(ai.assignee);
              return {
                id: `task-rand-${Date.now()}-${index}`,
                title: ai.title,
                assignee: tm.name,
                avatar: tm.avatar,
                priority: ai.priority || "Medium",
                deadline: ai.deadline || new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], // 3 days from now
                status: "Pending",
                category: ai.category || "Backend",
                matchKeywords: ai.matchKeywords || [ai.title.split(" ")[0].toLowerCase()]
              };
            }),
            jiraTickets: (aiResult.jiraTickets || []).map((t, index) => {
              const tm = resolveTeamMember(t.assignee);
              return {
                id: t.id || `JIRA-RAND-${100 + index}`,
                title: t.title,
                type: t.type || "Story",
                priority: t.priority || "Medium",
                assignee: tm.name,
                description: t.description || "Task automatically generated from audio upload."
              };
            }),
            emailDraft: {
              subject: aiResult.emailDraft?.subject || `Meeting Summary: ${aiResult.title}`,
              body: aiResult.emailDraft?.body || `Here is a summary of our meeting.`
            },
            transcript: aiResult.transcript || [
              { speaker: "Sarah Jenkins", time: "0:00", text: rawText }
            ]
          };

          progressVal = 95;
          progressBar.style.width = "95%";
          processingTitle.textContent = "Formulating Mail Sync...";
          processingStatus.textContent = "Writing email summaries and finalizing webhook integrations...";

          setTimeout(() => {
            progressVal = 100;
            progressBar.style.width = "100%";

            // Add meeting to database
            meetings.push(cleanMeeting);
            saveMeetingsToStorage();
            logEdit("meeting_add", `Uploaded meeting "${cleanMeeting.title}" via API`);

            showToast(`AI Pipeline complete. Processed "${cleanMeeting.title}"!`);

            setTimeout(() => {
              processingVisualizer.style.display = "none";
              uploadZone.style.display = "flex";
              document.querySelector(".demo-picker-section").style.display = "block";
              
              // Render dashboard updates
              renderDashboardStats();
              renderDemoPicker();

              // Open meeting in hub
              openMeetingDetails(cleanMeeting.id);
            }, 800);
          }, 1000);

        } catch (err) {
          clearInterval(audioProgressInterval);
          
          // Reset display state
          processingVisualizer.style.display = "none";
          uploadZone.style.display = "flex";
          document.querySelector(".demo-picker-section").style.display = "block";
          
          showToast(`Pipeline Error: ${handleApiError(err)}`, "error");
        }
      })();
    }
  }

