      const newNotes = document.getElementById("input-edit-lecture-notes").value.trim();
      const oldNotes = (currentActiveMeeting.class_notes && currentActiveMeeting.class_notes.lecture_notes) || "";
      if (!currentActiveMeeting.class_notes) currentActiveMeeting.class_notes = {};
      currentActiveMeeting.class_notes.lecture_notes = newNotes;
