  // Generate AI Notes
  document.getElementById("btn-generate-lecture-notes").addEventListener("click", async () => {
    if (!currentActiveMeeting) return;
    const transcriptText = (currentActiveMeeting.transcript || [])
      .map(t => t.text || "").join(". ");
    if (!transcriptText) {
      showToast("No transcript available to analyze. Upload an audio file or add a transcript.", "error");
      return;
    }
    showToast("Generating AI lecture notes...", "info");
    try {
      const res = await fetch("/api/analyze/class", {
        method: "POST", headers: {"Content-Type":"application/json","X-CSRF-Token":await ensureCsrfToken()},
        body: JSON.stringify({transcript: transcriptText})
      });
      const d = await res.json();
      if (!d.success) { showToast(d.error || "Analysis failed.", "error"); return; }
      if (!currentActiveMeeting.class_notes) currentActiveMeeting.class_notes = {};
      const n = d.classNotes;
      currentActiveMeeting.class_notes.lecture_notes = n.lecture_notes || "No notes generated.";
      currentActiveMeeting.class_notes.concepts = (n.concepts || []).map(c =>
        typeof c === "string" ? {term: "Concept", definition: c} : c
      );
      currentActiveMeeting.class_notes.study_guide = n.study_guide || [];
      currentActiveMeeting.class_notes.qa = (n.qa || []).map(q =>
        typeof q === "string" ? {question: q, answer: ""} : q
      );
      if (d.summary && currentActiveMeeting.summary) {
        currentActiveMeeting.summary.overview = d.summary;
      }
      saveMeetingsToStorage();
      renderLectureNotesTab(currentActiveMeeting);
      renderClassConceptsTab(currentActiveMeeting);
      renderStudyGuideTab(currentActiveMeeting);
      renderClassQaTab(currentActiveMeeting);
      showToast("AI lecture notes generated successfully!", "success");
    } catch { showToast("Network error during analysis.", "error"); }
  });

