  function renderDetailActionItems(meet) {
    detailActionItemsTbody.innerHTML = "";
    if (!meet.actionItems || meet.actionItems.length === 0) {
      detailActionItemsTbody.innerHTML = `
        <tr>
          <td colspan="5" style="text-align: center; color: var(--text-muted); padding: 2rem;">
            <i class="fa-solid fa-list-check" style="font-size: 1.5rem; margin-bottom: 0.5rem; display: block;"></i>
            No action items assigned.
          </td>
        </tr>
      `;
      return;
    }
    var sortedItems = meet.actionItems.slice().sort(function(a,b){
      if(a.status==="Completed"&&b.status!=="Completed")return 1;
      if(a.status!=="Completed"&&b.status==="Completed")return -1;
      return 0;
    });
    sortedItems.forEach(function(item){
      const tr = document.createElement("tr");
      
      const badgeClass = item.status === "Completed" ? "badge-completed" : item.priority === "High" ? "badge-high" : item.priority === "Medium" ? "badge-medium" : "badge-low";
      const statusText = item.status === "Completed" ? "Completed" : item.priority;

      tr.innerHTML = `
        <td>
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <input type="checkbox" ${item.status === 'Completed' ? 'checked' : ''} class="task-checkbox" data-task-id="${item.id}" style="cursor: pointer;">
            <span style="${item.status === 'Completed' ? 'text-decoration: line-through; color: var(--text-muted);' : ''}">${item.title}</span>
          </div>
        </td>
        <td>
          <div class="assignee-cell">
            <img src="${item.avatar}" alt="" class="assignee-avatar">
            <span>${item.assignee.split(" ")[0]}</span>
          </div>
        </td>
        <td>
          <span class="badge ${badgeClass}">${statusText}</span>
        </td>
        <td style="font-family: monospace; color: var(--text-secondary);">${item.deadline}</td>
        <td>
          <div style="display: flex; justify-content: center; gap: 0.5rem;">
            <button class="edit-task-btn" data-task-id="${item.id}" style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 0.8rem; padding: 0.1rem; transition: color 0.2s;" title="Edit Task"><i class="fa-solid fa-pen"></i></button>
            <button class="delete-task-btn" data-task-id="${item.id}" style="background: none; border: none; color: var(--danger); opacity: 0.8; cursor: pointer; font-size: 0.8rem; padding: 0.1rem; transition: color 0.2s;" title="Delete Task"><i class="fa-solid fa-trash"></i></button>
          </div>
        </td>
      `;

      // Checkbox listener
      const checkbox = tr.querySelector(".task-checkbox");
      checkbox.addEventListener("change", (e) => {
        e.stopPropagation();
        toggleTaskStatus(item.id, e.target.checked);
      });

      // Edit listener
      tr.querySelector(".edit-task-btn").addEventListener("click", () => {
        openActionItemModal(item);
      });

      // Delete listener
      tr.querySelector(".delete-task-btn").addEventListener("click", () => {
        if (confirm(`Are you sure you want to delete the action item: "${item.title}"?`)) {
          deleteActionItem(item.id);
        }
      });

      detailActionItemsTbody.appendChild(tr);
    });
  }

  function toggleTaskStatus(taskId, isCompleted) {
    meetings.forEach(m => {
      const task = m.actionItems.find(t => t.id === taskId);
      if (task) {
        const oldStatus = task.status;
        task.status = isCompleted ? "Completed" : "Pending";
        logEdit("task_toggle", `${isCompleted ? "Completed" : "Reopened"} task "${task.title}"`, { oldValue: oldStatus, newValue: task.status, field: "status" });
      }
    });

    saveMeetingsToStorage();
    showToast(`Task status updated!`);
    
    // Preserve scroll position before re-render to prevent scroll-to-top
    var scrollers = document.querySelectorAll(".scrollable-column");
    var scrollTops = []; scrollers.forEach(function(s){scrollTops.push(s.scrollTop);});
    if (currentActiveMeeting) {
      renderDetailActionItems(currentActiveMeeting);
    }
    renderDashboardStats();
    renderTaskTracker();
    scrollers.forEach(function(s,i){s.scrollTop=scrollTops[i];});
  }

  // --- AUDIO SIMULATOR ENGINE ---
  function resetAudioPlayer() {
    if (realAudioObj) {
      realAudioObj.pause();
      realAudioObj = null;
    }
    clearInterval(audioPlayInterval);
    isPlaying = false;
    audioCurrentTime = 0;
    if (btnPlayAudio) { btnPlayAudio.innerHTML = '<i class="fa-solid fa-play"></i>'; btnPlayAudio.setAttribute('aria-label', 'Play audio'); }
    if (audioScrubberFill) audioScrubberFill.style.width = "0%";
    if (audioTimer) audioTimer.textContent = `00:00 / ${formatTime(audioDuration)}`;
    
    // Remove active transcript highlights
    if (detailTranscriptBox) {
      const lines = detailTranscriptBox.querySelectorAll(".transcript-line");
      lines.forEach(l => l.style.backgroundColor = "transparent");
    }
  }

  function toggleAudioPlay() {
    if (isPlaying) {
      if (realAudioObj) {
        realAudioObj.pause();
      }
      clearInterval(audioPlayInterval);
      isPlaying = false;
      btnPlayAudio.innerHTML = '<i class="fa-solid fa-play"></i>';
      btnPlayAudio.setAttribute('aria-label', 'Play audio');
    } else {
      isPlaying = true;
      btnPlayAudio.innerHTML = '<i class="fa-solid fa-pause"></i>';
      btnPlayAudio.setAttribute('aria-label', 'Pause audio');
      
      if (realAudioObj) {
        realAudioObj.currentTime = audioCurrentTime;
        realAudioObj.play().catch(err => {
          console.error("Audio playback error:", err);
          showToast("Audio playback error. Falling back to simulation.", "error");
          realAudioObj = null;
        });
      }
      
      audioPlayInterval = setInterval(() => {
        if (realAudioObj) {
          audioCurrentTime = realAudioObj.currentTime;
        } else {
          audioCurrentTime += 1;
        }
        
        if (audioCurrentTime >= audioDuration) {
          resetAudioPlayer();
        } else {
          updateAudioProgress();
        }
      }, realAudioObj ? 250 : 1000);
    }
  }

  function jumpAudioTo(seconds) {
    audioCurrentTime = Math.min(seconds, audioDuration);
    if (realAudioObj) {
      realAudioObj.currentTime = audioCurrentTime;
    }
    updateAudioProgress();
    if (!isPlaying) {
      toggleAudioPlay();
    }
  }

  function updateAudioProgress() {
    const pct = (audioCurrentTime / audioDuration) * 100;
    audioScrubberFill.style.width = `${pct}%`;
    audioTimer.textContent = `${formatTime(audioCurrentTime)} / ${formatTime(audioDuration)}`;

    // Sync transcripts based on timestamp
    const lines = detailTranscriptBox.querySelectorAll(".transcript-line");
    let activeIndex = -1;

    lines.forEach((line, index) => {
      const lineTime = line.getAttribute("data-time");
      const parts = lineTime.split(":");
      const lineSecs = parseInt(parts[0]) * 60 + parseInt(parts[1]);

      if (audioCurrentTime >= lineSecs) {
        activeIndex = index;
      }
    });

    lines.forEach((line, index) => {
      if (index === activeIndex) {
        line.style.backgroundColor = "rgba(99, 102, 241, 0.15)";
        line.scrollIntoView({ behavior: "smooth", block: "nearest" });
      } else {
        line.style.backgroundColor = "transparent";
      }
    });
  }

  // Audio events
  btnPlayAudio.addEventListener("click", toggleAudioPlay);
  
  audioScrubber.addEventListener("click", (e) => {
    const rect = audioScrubber.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const pct = clickX / rect.width;
    const targetSecs = Math.floor(pct * audioDuration);
    jumpAudioTo(targetSecs);
  });

  // Back button
  btnBackToMeetings.addEventListener("click", () => {
    resetAudioPlayer();
    currentActiveMeeting = null;
    renderMeetingsHub();
  });

  // Tab switcher in meeting details
  const tabButtons = document.querySelectorAll(".tab-nav-btn");
  const tabPanes = document.querySelectorAll(".detail-tab-pane");

  tabButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      tabButtons.forEach(b => b.classList.remove("active"));
      tabPanes.forEach(p => p.classList.remove("active"));

      btn.classList.add("active");
      const targetTab = btn.getAttribute("data-tab");
      const targetEl = document.getElementById(targetTab);
      if (targetEl) targetEl.classList.add("active");

      // Ensure right content is rendered when opening these tabs
      if (targetTab === "tab-calendar" && currentActiveMeeting) renderDetailCalendar(currentActiveMeeting);
      if (targetTab === "tab-edit-history" && currentActiveMeeting) renderMeetingEditHistory(currentActiveMeeting);
    });
  });

  // Copy email draft
  document.getElementById("btn-copy-email").addEventListener("click", () => {
    if (currentActiveMeeting) {
      const text = `${currentActiveMeeting.emailDraft.subject}\n\n${currentActiveMeeting.emailDraft.body}`;
      navigator.clipboard.writeText(text).then(() => {
        showToast("Email draft copied to clipboard!");
      });
    }
  });

  // Export Jira mock
  document.getElementById("btn-export-all-jira").addEventListener("click", () => {
    showToast("Export successful! Generated Jira cards pushed to standard developer API webhook node.", "success");
  });

  // --- TASK TRACKER GLOBAL SCREEN ---
  function renderTaskTracker() {
    globalTasksTbody.innerHTML = "";
    
    let allTasks = [];
    meetings.forEach(m => {
      const meetTitle = m.title;
      const meetId = m.id;
      m.actionItems.forEach(item => {
        allTasks.push({ ...item, meetingTitle: meetTitle, meetingId: meetId });
      });
    });

    // Sort by deadline, then priority
    const priorityWeight = { High: 3, Medium: 2, Low: 1 };
    allTasks.sort((a, b) => {
      if (a.status === "Completed" && b.status !== "Completed") return 1;
      if (a.status !== "Completed" && b.status === "Completed") return -1;
      return priorityWeight[b.priority] - priorityWeight[a.priority];
    });

    taskBoardCounter.textContent = `${allTasks.filter(t => t.status !== 'Completed').length} Tasks Pending`;

    if (allTasks.length === 0) {
      globalTasksTbody.innerHTML = `
        <tr>
          <td colspan="5" style="text-align: center; color: var(--text-muted); padding: 3rem;">
            No actions generated yet. Process a meeting to get started.
          </td>
        </tr>
      `;
      return;
    }

    allTasks.forEach(item => {
      const tr = document.createElement("tr");
      tr.id = `global-tr-${item.id}`;
      
      const badgeClass = item.status === "Completed" ? "badge-completed" : item.priority === "High" ? "badge-high" : item.priority === "Medium" ? "badge-medium" : "badge-low";
      const statusText = item.status === "Completed" ? "Completed" : item.priority;

      tr.innerHTML = `
        <td>
          <input type="checkbox" ${item.status === 'Completed' ? 'checked' : ''} class="global-task-chk" data-task-id="${item.id}" style="cursor: pointer;">
        </td>
        <td>
          <div style="display: flex; flex-direction: column;">
            <span style="${item.status === 'Completed' ? 'text-decoration: line-through; color: var(--text-muted);' : 'font-weight: 500;'}">${item.title}</span>
            <span style="font-size: 0.75rem; color: var(--text-muted);">Source: ${item.meetingTitle}</span>
          </div>
        </td>
        <td>
          <div class="assignee-cell">
            <img src="${item.avatar}" alt="" class="assignee-avatar">
            <span>${item.assignee}</span>
          </div>
        </td>
        <td>
          <span class="badge ${badgeClass}">${statusText}</span>
        </td>
        <td style="font-family: monospace; color: var(--text-secondary);">${item.deadline}</td>
      `;

      const checkbox = tr.querySelector(".global-task-chk");
      checkbox.addEventListener("change", (e) => {
        e.stopPropagation();
        toggleTaskStatus(item.id, e.target.checked);
      });

      globalTasksTbody.appendChild(tr);
    });

    // Populate preset dropdown
    selectPresetActivity.innerHTML = '<option value="">-- Choose a Preset Activity --</option>';
    activities.forEach(act => {
      // Only list activity if related task is NOT completed
      let taskCompleted = false;
      meetings.forEach(m => {
        const t = m.actionItems.find(item => item.id === act.taskId);
        if (t && t.status === "Completed") {
          taskCompleted = true;
        }
      });

      if (!taskCompleted) {
        const option = document.createElement("option");
        option.value = act.id;
        option.textContent = `${act.author}: ${act.text.substring(0, 35)}...`;
        selectPresetActivity.appendChild(option);
      }
    });

    // Re-render calendar if tab active
    const activeSubTab = document.querySelector(".sub-tab-btn.active");
    if (activeSubTab && activeSubTab.getAttribute("data-subtab") === "tasks-calendar-tab") {
      renderCalendar();
    }
  }

  // --- CALENDAR & SUB-TABS INTERACTIVE ENGINE ---
  const _now = new Date();
  let calendarCurrentDate = new Date(_now.getFullYear(), _now.getMonth(), 1);
  let calendarSelectedDateStr = `${_now.getFullYear()}-${(_now.getMonth()+1).toString().padStart(2,"0")}-${_now.getDate().toString().padStart(2,"0")}`;

  // Sub tab navigation listener
  const subTabButtons = document.querySelectorAll(".sub-tab-btn");
  const tasksTabPanes = document.querySelectorAll(".tasks-tab-pane");

  subTabButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      subTabButtons.forEach(b => {
        b.classList.remove("active");
        b.style.color = "var(--text-secondary)";
        b.style.borderBottomColor = "transparent";
      });
      tasksTabPanes.forEach(p => p.style.display = "none");

      btn.classList.add("active");
      btn.style.color = "var(--text-primary)";
      btn.style.borderBottomColor = "var(--accent-primary)";

      const targetTabId = btn.getAttribute("data-subtab");
      const targetPane = document.getElementById(targetTabId);
      if (targetPane) {
        targetPane.style.display = "block";
      }

      if (targetTabId === "tasks-calendar-tab") {
        renderCalendar();
      }
    });
  });

  // Calendar month navigation
  document.getElementById("btn-prev-month").addEventListener("click", () => {
    calendarCurrentDate.setMonth(calendarCurrentDate.getMonth() - 1);
    renderCalendar();
  });

  document.getElementById("btn-next-month").addEventListener("click", () => {
    calendarCurrentDate.setMonth(calendarCurrentDate.getMonth() + 1);
    renderCalendar();
  });

  // --- CALENDAR RIGHT PANEL TABS ---
  document.querySelectorAll(".calendar-right-tab").forEach(tab => {
    tab.addEventListener("click", () => {
      document.querySelectorAll(".calendar-right-tab").forEach(t => t.classList.remove("active"));
      tab.classList.add("active");
      const target = tab.getAttribute("data-rtab");
      document.querySelectorAll(".calendar-right-pane").forEach(p => {
        p.style.display = "none";
        p.classList.remove("active");
      });
      const pane = document.getElementById(target);
      if (pane) { pane.style.display = "flex"; pane.classList.add("active"); }
    });
  });

  function renderCalendar() {
    const titleEl = document.getElementById("calendar-month-year");
    const daysGrid = document.getElementById("calendar-days-grid");
    if (!titleEl || !daysGrid) return;
    const year = calendarCurrentDate.getFullYear();
    const month = calendarCurrentDate.getMonth();

    const monthNames = [
      "January", "February", "March", "April", "May", "June",
      "July", "August", "September", "October", "November", "December"
    ];

    titleEl.textContent = `${monthNames[month]} ${year}`;

    daysGrid.innerHTML = "";

    // Group action items by deadline date YYYY-MM-DD
    const taskDeadlines = {};
    meetings.forEach(meet => {
      meet.actionItems.forEach(item => {
        const d = item.deadline; // YYYY-MM-DD
        if (d) {
          if (!taskDeadlines[d]) {
            taskDeadlines[d] = [];
          }
          taskDeadlines[d].push({ ...item, meetingTitle: meet.title });
        }
      });
    });

    // Group meetings by upload date YYYY-MM-DD
    const meetingUploadDates = {};
    meetings.forEach(meet => {
      if (meet.date) {
        const mDate = _parseDate(meet.date);
        if (mDate) {
          const dateKey = _dateKey(mDate);
          if (dateKey) {
            if (!meetingUploadDates[dateKey]) meetingUploadDates[dateKey] = [];
            meetingUploadDates[dateKey].push(meet);
          }
        }
      }
    });

    const firstDayIndex = new Date(year, month, 1).getDay();
    const numberOfDays = new Date(year, month + 1, 0).getDate();

    // Render empty cells for leading days
    for (let i = 0; i < firstDayIndex; i++) {
      const emptyCell = document.createElement("div");
      emptyCell.className = "calendar-day-cell empty-cell";
      daysGrid.appendChild(emptyCell);
    }

    // Render month days
    for (let day = 1; day <= numberOfDays; day++) {
      const dateStr = `${year}-${(month + 1).toString().padStart(2, "0")}-${day.toString().padStart(2, "0")}`;
      const dayCell = document.createElement("div");
      dayCell.className = "calendar-day-cell";
      dayCell.setAttribute("data-date", dateStr);
      var dayText = document.createElement("span");
      dayText.textContent = day;
      dayCell.appendChild(dayText);

      // Highlight Today
      const today = new Date();
      if (year === today.getFullYear() && month === today.getMonth() && day === today.getDate()) {
        dayCell.classList.add("today");
      }

      // Add colored indicators
      var indWrap = document.createElement("div");
      indWrap.style.cssText = "display:flex;gap:2px;margin-top:2px;";
      var hasAny = false;
      if (taskDeadlines[dateStr] && taskDeadlines[dateStr].length > 0) {
        dayCell.classList.add("has-deadline");
        var dl = document.createElement("span");
        dl.className = "cal-indicator dl";
        dl.title = taskDeadlines[dateStr].length+" deadline(s)";
        indWrap.appendChild(dl);
        hasAny = true;
      }
      if (meetingUploadDates[dateStr] && meetingUploadDates[dateStr].length > 0) {
        dayCell.classList.add("has-meeting");
        var mt = document.createElement("span");
        mt.className = "cal-indicator mt";
        mt.title = meetingUploadDates[dateStr].length+" meeting(s)";
        indWrap.appendChild(mt);
        hasAny = true;
      }
      if (hasAny) dayCell.appendChild(indWrap);

      // If this day is selected
      if (calendarSelectedDateStr === dateStr) {
        dayCell.classList.add("selected");
      }

      dayCell.addEventListener("click", () => {
        document.querySelectorAll(".calendar-day-cell.selected").forEach(el => el.classList.remove("selected"));
        dayCell.classList.add("selected");
        calendarSelectedDateStr = dateStr;
        renderSelectedDayDeadlines(dateStr, taskDeadlines[dateStr] || []);
        renderSelectedDayMeetings(dateStr);
        renderMyTasks(dateStr);
      });

      daysGrid.appendChild(dayCell);
    }

    // Initialize/Render detail view for selected date
    const selectedDateTasks = taskDeadlines[calendarSelectedDateStr] || [];
    renderSelectedDayDeadlines(calendarSelectedDateStr, selectedDateTasks);

    // Render meetings uploaded on selected date
    renderSelectedDayMeetings(calendarSelectedDateStr);

    // Render user tasks for selected date
    renderMyTasks(calendarSelectedDateStr);

    // Mark calendar cells that have user tasks
    document.querySelectorAll(".calendar-day-cell").forEach(cell => {
      const ds = cell.getAttribute("data-date");
      if (ds && userTasks[ds] && userTasks[ds].length > 0) {
        cell.classList.add("has-user-task");
        var wrap = cell.querySelector("div:last-child") || (function(){var w=document.createElement("div");w.style.cssText="display:flex;gap:2px;margin-top:2px;";cell.appendChild(w);return w;})();
        var ts = document.createElement("span");
        ts.className = "cal-indicator ts";
        ts.title = userTasks[ds].length+" task(s)";
        wrap.appendChild(ts);
      }
    });

    // Personal events stored in localStorage
    const empDeadlines = JSON.parse(localStorage.getItem("echoaction_emp_deadlines") || "[]");
    const empAlerts = JSON.parse(localStorage.getItem("echoaction_emp_alerts") || "[]");
    const empMeetings = JSON.parse(localStorage.getItem("echoaction_emp_meetings") || "[]");

    // Mark calendar cells with personal events
    document.querySelectorAll(".calendar-day-cell").forEach(cell => {
      const ds = cell.getAttribute("data-date");
      if (!ds) return;
      if (empDeadlines.some(e => e.date === ds)) cell.classList.add("has-deadline");
      if (empAlerts.some(e => e.date === ds)) cell.classList.add("has-meeting");
      if (empMeetings.some(e => e.date === ds)) cell.classList.add("has-meeting");
    });

    // Attach event handlers for personal event buttons
    setTimeout(() => {
      const dlBtn = document.getElementById("cal-set-deadline");
      const alertBtn = document.getElementById("cal-set-alert");
      const meetBtn = document.getElementById("cal-set-meeting");
      if (dlBtn) dlBtn.onclick = function() {
        showFormOverlay("Add Deadline", [
          {key:"title",id:"emp-dl-title",label:"Deadline Title",type:"text",ph:"e.g. Project submission"},
          {key:"date",id:"emp-dl-date",label:"Date",type:"date",val:calendarSelectedDateStr},
          {key:"time",id:"emp-dl-time",label:"Time",type:"time",ph:"Optional",optional:true}
        ], function(data) {
          const dl = JSON.parse(localStorage.getItem("echoaction_emp_deadlines") || "[]");
          dl.push({id:"ed"+Date.now(), title:data.title, date:data.date, time:data.time||""});
          localStorage.setItem("echoaction_emp_deadlines", JSON.stringify(dl));
          showToast("Deadline added: " + data.title, "success");
          renderCalendar();
        });
      };
      if (alertBtn) alertBtn.onclick = function() {
        showFormOverlay("Set Alert", [
          {key:"title",id:"emp-al-title",label:"Alert Title",type:"text",ph:"e.g. Project deadline"},
          {key:"date",id:"emp-al-date",label:"Date",type:"date",val:calendarSelectedDateStr},
          {key:"time",id:"emp-al-time",label:"Time",type:"time",ph:"HH:MM"}
        ], function(data) {
          const al = JSON.parse(localStorage.getItem("echoaction_emp_alerts") || "[]");
          al.push({id:"ea"+Date.now(), title:data.title, date:data.date, time:data.time});
          localStorage.setItem("echoaction_emp_alerts", JSON.stringify(al));
          showToast("Alert set for " + data.title, "success");
          renderCalendar();
        });
      };
      if (meetBtn) meetBtn.onclick = function() {
        showFormOverlay("Schedule Meeting", [
          {key:"title",id:"emp-meet-title",label:"Meeting Title",type:"text",ph:"e.g. Team standup"},
          {key:"date",id:"emp-meet-date",label:"Date",type:"date",val:calendarSelectedDateStr},
          {key:"time",id:"emp-meet-time",label:"Time",type:"time",ph:"HH:MM"},
          {key:"duration",id:"emp-meet-dur",label:"Duration (min)",type:"number",ph:"30"},
          {key:"link",id:"emp-meet-link",label:"Meeting Link (optional)",type:"text",ph:"e.g. https://zoom.us/j/123"},
          {key:"attendees",id:"emp-meet-att",label:"Attendees (comma separated, optional)",type:"text",ph:"e.g. alice@example.com, bob@example.com"},
          {key:"actionItems",id:"emp-meet-act",label:"Action Items (comma, optional)",type:"text",ph:"e.g. Review code, Send report"},
          {key:"notes",id:"emp-meet-notes",label:"Notes / Agenda (optional)",type:"text",ph:"Notes...",tag:"textarea"}
        ], function(data) {
          const aiList = (data.actionItems||"").split(",").map(function(s){return s.trim();}).filter(Boolean).map(function(t,i){return {id:"ai"+Date.now()+"-"+i, title:t, assignee:"", status:"Pending", deadline:"", priority:"Medium"};});
          const mt = JSON.parse(localStorage.getItem("echoaction_emp_meetings") || "[]");
          mt.push({id:"em"+Date.now(), title:data.title, date:data.date, time:data.time, duration:data.duration||"30", link:data.link||"", attendees:(data.attendees||"").split(",").map(function(s){return s.trim();}).filter(Boolean), actionItems:aiList, notes:data.notes||""});
          localStorage.setItem("echoaction_emp_meetings", JSON.stringify(mt));
          showToast("Meeting scheduled: " + data.title, "success");
          renderCalendar();
        });
      };
    }, 50);
  }

  // --- USER TASKS (My Tasks) ---
  let userTasks = {};
  function loadUserTasks() {
    try { userTasks = JSON.parse(localStorage.getItem("echoaction_user_tasks") || "{}"); } catch(e) { userTasks = {}; }
  }
  function saveUserTasks() {
    localStorage.setItem("echoaction_user_tasks", JSON.stringify(userTasks));
  }
  loadUserTasks();

  function renderMyTasks(dateStr) {
    const listEl = document.getElementById("my-tasks-list");
    const inputEl = document.getElementById("my-task-input");
    const addBtn = document.getElementById("btn-add-my-task");
    const priorityEl = document.getElementById("my-task-priority");
    const categoryEl = document.getElementById("my-task-category");
    const descEl = document.getElementById("my-task-desc");
    if (!listEl) return;

    const priorityColors = { low: "#6b7280", medium: "#3b82f6", high: "#f59e0b", urgent: "#ef4444" };
    const priorityLabels = { low: "Low", medium: "Medium", high: "High", urgent: "Urgent" };
    const categoryIcons = { work: "fa-briefcase", personal: "fa-user", "meeting-prep": "fa-calendar-check", "follow-up": "fa-reply", deadline: "fa-clock", other: "fa-tag" };
    const categoryLabels = { work: "Work", personal: "Personal", "meeting-prep": "Meeting Prep", "follow-up": "Follow-up", deadline: "Deadline", other: "Other" };

    const tasks = userTasks[dateStr] || [];
    listEl.innerHTML = "";

    if (tasks.length === 0) {
      listEl.innerHTML = '<div style="text-align:center;padding:1.5rem 1rem;color:var(--text-muted);"><i class="fa-solid fa-circle-plus" style="font-size:1.3rem;margin-bottom:0.4rem;display:block;opacity:0.4;"></i><p style="font-size:0.8rem;">No tasks added yet. Fill the form above and click Add.</p></div>';
    } else {
      tasks.slice().sort((a,b)=>(a.done?1:0)-(b.done?1:0)).forEach((task, idx) => {
        const card = document.createElement("div");
        const pColor = priorityColors[task.priority || "medium"];
        const cIcon = categoryIcons[task.category || "work"];
        const cLabel = categoryLabels[task.category || "work"];
        const pLabel = priorityLabels[task.priority || "medium"];
        card.className = "my-task-card";
        card.style.cssText = `display:flex;flex-direction:column;gap:0.4rem;padding:0.65rem 0.85rem;background:rgba(16,185,129,0.06);border:1px solid rgba(16,185,129,0.2);border-left:3px solid ${pColor};border-radius:10px;transition:all 0.2s;`;
        card.innerHTML = `
          <div style="display:flex;align-items:center;gap:0.5rem;">
            <i class="fa-solid fa-circle-check" style="color:var(--success);font-size:0.85rem;cursor:pointer;flex-shrink:0;" data-action="toggle" title="Toggle complete"></i>
            <span style="flex:1;font-size:0.85rem;color:var(--text-primary);${task.done ? 'text-decoration:line-through;opacity:0.5;' : ''}">${task.text}</span>
            <span style="font-size:0.6rem;padding:0.15rem 0.4rem;border-radius:6px;background:${pColor}22;color:${pColor};font-weight:600;flex-shrink:0;">${pLabel}</span>
            <button style="background:none;border:none;color:var(--accent-primary);cursor:pointer;font-size:0.7rem;padding:0.15rem;flex-shrink:0;" data-action="edit" title="Edit"><i class="fa-solid fa-pen"></i></button>
            <button style="background:none;border:none;color:var(--danger);cursor:pointer;font-size:0.75rem;padding:0.15rem;flex-shrink:0;opacity:0.6;transition:opacity 0.15s;" data-action="delete" title="Delete" onmouseenter="this.style.opacity='1'" onmouseleave="this.style.opacity='0.6'"><i class="fa-solid fa-trash"></i></button>
          </div>
          <div style="display:flex;align-items:center;gap:0.6rem;padding-left:1.35rem;">
            <span style="font-size:0.65rem;color:var(--text-muted);display:flex;align-items:center;gap:0.25rem;"><i class="fa-solid ${cIcon}" style="font-size:0.55rem;"></i>${cLabel}</span>
            ${task.description ? `<span style="font-size:0.65rem;color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:200px;" title="${task.description.replace(/"/g, '&quot;')}">${task.description}</span>` : ''}
          </div>
        `;
        if (task.done) card.style.opacity = "0.6";

        card.querySelector("[data-action='toggle']").addEventListener("click", () => {
          task.done = !task.done;
          saveUserTasks();
          logEdit("task_toggle", `${task.done ? "Completed" : "Reopened"} task "${task.text}"`);
          renderMyTasks(dateStr);
          renderCalendar();
        });
        card.querySelector("[data-action='delete']").addEventListener("click", () => {
          if (!confirm(`Delete task "${task.text}"?`)) return;
          tasks.splice(idx, 1);
          if (tasks.length === 0) delete userTasks[dateStr];
          saveUserTasks();
          logEdit("task_delete", `Deleted personal task "${task.text}"`);
          renderMyTasks(dateStr);
          renderCalendar();
          showToast("Task deleted.");
        });
        card.querySelector("[data-action='edit']").addEventListener("click", () => {
          // Replace card with inline edit form
          const editCard = document.createElement("div");
          editCard.className = "my-task-card";
          editCard.style.cssText = `display:flex;flex-direction:column;gap:0.5rem;padding:0.7rem 0.85rem;background:rgba(99,102,241,0.06);border:1px solid rgba(255,255,255,0.08);border-left:3px solid var(--accent-primary);border-radius:10px;`;
          editCard.innerHTML = `
            <input type="text" class="eh-edit-input" value="${task.text.replace(/"/g, '&quot;')}" style="padding:0.4rem 0.6rem;border-radius:6px;border:1px solid var(--card-border);background:rgba(255,255,255,0.04);color:var(--text-primary);font-size:0.82rem;width:100%;box-sizing:border-box;">
            <textarea class="eh-edit-input" rows="2" style="padding:0.4rem 0.6rem;border-radius:6px;border:1px solid var(--card-border);background:rgba(255,255,255,0.04);color:var(--text-primary);font-size:0.78rem;width:100%;box-sizing:border-box;resize:vertical;" placeholder="Description...">${(task.description || "").replace(/</g, "&lt;").replace(/>/g, "&gt;")}</textarea>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:0.4rem;">
              <select class="eh-edit-input" style="padding:0.35rem 0.5rem;border-radius:6px;border:1px solid var(--card-border);background:rgba(255,255,255,0.04);color:var(--text-primary);font-size:0.75rem;">
                <option value="low" ${task.priority === "low" ? "selected" : ""}>Low</option>
                <option value="medium" ${task.priority === "medium" || !task.priority ? "selected" : ""}>Medium</option>
                <option value="high" ${task.priority === "high" ? "selected" : ""}>High</option>
                <option value="urgent" ${task.priority === "urgent" ? "selected" : ""}>Urgent</option>
              </select>
              <select class="eh-edit-input" style="padding:0.35rem 0.5rem;border-radius:6px;border:1px solid var(--card-border);background:rgba(255,255,255,0.04);color:var(--text-primary);font-size:0.75rem;">
                <option value="work" ${task.category === "work" ? "selected" : ""}>Work</option>
                <option value="personal" ${task.category === "personal" ? "selected" : ""}>Personal</option>
                <option value="meeting-prep" ${task.category === "meeting-prep" ? "selected" : ""}>Meeting Prep</option>
                <option value="follow-up" ${task.category === "follow-up" ? "selected" : ""}>Follow-up</option>
                <option value="deadline" ${task.category === "deadline" ? "selected" : ""}>Deadline</option>
                <option value="other" ${task.category === "other" ? "selected" : ""}>Other</option>
              </select>
            </div>
            <div style="display:flex;gap:0.4rem;justify-content:flex-end;">
              <button class="btn btn-secondary eh-edit-cancel" style="padding:0.3rem 0.7rem;font-size:0.75rem;">Cancel</button>
              <button class="btn btn-primary eh-edit-save" style="padding:0.3rem 0.7rem;font-size:0.75rem;background:var(--success);border-color:var(--success);">Save</button>
            </div>
          `;
          card.replaceWith(editCard);

          editCard.querySelector(".eh-edit-cancel").addEventListener("click", () => {
            renderMyTasks(dateStr);
          });

          editCard.querySelector(".eh-edit-save").addEventListener("click", () => {
            const inputs = editCard.querySelectorAll(".eh-edit-input");
            const newName = inputs[0].value.trim();
            const newDesc = inputs[1].value.trim();
            const newPriority = inputs[2].value;
            const newCategory = inputs[3].value;
            if (!newName) { showToast("Task name cannot be empty.", "error"); return; }
            task.text = newName;
            task.description = newDesc;
            task.priority = newPriority;
            task.category = newCategory;
            saveUserTasks();
            logEdit("task_edit", `Edited personal task to "${task.text}"`);
            renderMyTasks(dateStr);
            renderCalendar();
            showToast("Task updated!");
          });
        });
        listEl.appendChild(card);
      });
    }

    // Add task handler
    if (addBtn && inputEl) {
      addBtn.onclick = () => {
        const text = inputEl.value.trim();
        if (!text) { showToast("Please enter a task.", "error"); return; }
        const priority = priorityEl ? priorityEl.value : "medium";
        const category = categoryEl ? categoryEl.value : "work";
        const description = descEl ? descEl.value.trim() : "";
        if (!userTasks[dateStr]) userTasks[dateStr] = [];
        userTasks[dateStr].push({ text, done: false, priority, category, description, created: new Date().toISOString() });
        saveUserTasks();
        logEdit("task_add", `Added personal task "${text}"`);
        inputEl.value = "";
        if (descEl) descEl.value = "";
        renderMyTasks(dateStr);
        renderCalendar();
        showToast("Task added!");
      };
      inputEl.onkeydown = (e) => { if (e.key === "Enter") addBtn.click(); };
    }
  }

  // --- AUTOMATIC COMPLETION TRACKER ENGINE ---
  function printLog(text, color = "var(--text-secondary)") {
    const line = document.createElement("div");
    line.className = "console-line";
    line.style.color = color;
    line.innerHTML = `> ${text}`;
    consoleLogs.appendChild(line);
    consoleLogs.scrollTop = consoleLogs.scrollHeight;
  }

  function runAIEngineIngest(author, text, linkedTaskId = null) {
    consoleCurrentStatus.textContent = "Analyzing...";
    printLog("---------------------------------------------", "var(--text-muted)");
    printLog(`Webhoook Received from ${author}.`, "#f59e0b");
    printLog(`Payload: "${text}"`, "var(--text-primary)");
    printLog("Invoking Llama semantic reasoning parser...", "var(--accent-secondary)");

    setTimeout(() => {
      let matchedTask = null;
      let score = 0;

      // 1. If pre-configured task link is present (for presets)
      if (linkedTaskId) {
        meetings.forEach(m => {
          const task = m.actionItems.find(t => t.id === linkedTaskId);
          if (task && task.status !== "Completed") {
            matchedTask = task;
            score = 100;
          }
        });
      }

      // 2. Fallback or Manual parsing: Semantic Keyword Analysis
      if (!matchedTask) {
        const words = text.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "").split(/\s+/);
        let bestMatch = null;
        let highestScore = 0;

        meetings.forEach(m => {
          m.actionItems.forEach(t => {
            if (t.status !== "Completed") {
              let matchCount = 0;
              t.matchKeywords.forEach(keyword => {
                if (words.some(word => word.includes(keyword) || keyword.includes(word))) {
                  matchCount++;
                }
              });

              // Also check if author matches assignee first names
              const assigneeName = t.assignee.toLowerCase();
              const authorName = author.toLowerCase();
              let authorWeight = 0;
              if (authorName.includes(assigneeName.split(" ")[0])) {
                authorWeight = 1.5; // multiplier weight
              }

              const finalScore = Math.round((matchCount / t.matchKeywords.length) * 100 * (authorWeight || 1));
              
              if (finalScore > highestScore && finalScore > 25) {
                highestScore = finalScore;
                bestMatch = t;
              }
            }
          });
        });

        if (bestMatch) {
          matchedTask = bestMatch;
          score = Math.min(highestScore, 98); // cap similarity score
        }
      }

      // Action Match Result
      if (matchedTask) {
        printLog(`LLM Match success! Mapping confidence: ${score}%`, "var(--success)");
        printLog(`Action Item identified: "${matchedTask.title}"`, "var(--success)");
        printLog(`Assignee: ${matchedTask.assignee}`, "var(--text-primary)");
        printLog(`Applying status patch: SET STATUS = 'Completed'`, "var(--accent-primary)");

        // Update task
        matchedTask.status = "Completed";
        saveMeetingsToStorage();

        // Push matching activity to top of feed
        const newAct = {
          id: "act-live-" + Date.now(),
          type: author.includes("Marcus") || author.includes("Elena") || author.includes("Dan") ? "slack" : "git",
          author: author,
          source: author.includes("Marcus") || author.includes("Elena") || author.includes("Dan") ? "Slack Sync" : "Git Commit",
          text: text,
          timestamp: "Just now",
          taskId: matchedTask.id
        };
        activities.unshift(newAct);
        saveActivitiesToStorage();

        showToast(`Auto-Completed task: "${matchedTask.title}"`, "success");

        // Flash target row in green
        setTimeout(() => {
          const row = document.getElementById(`global-tr-${matchedTask.id}`);
          if (row) {
            row.style.transition = "background-color 0.5s ease";
            row.style.backgroundColor = "rgba(16, 185, 129, 0.2)";
            setTimeout(() => {
              row.style.backgroundColor = "transparent";
              renderTaskTracker();
            }, 1500);
          } else {
            renderTaskTracker();
          }
        }, 100);

      } else {
        printLog("Semantic query vector alignment failed.", "var(--danger)");
        printLog("Reason: No active pending tasks match this update text context.", "var(--text-muted)");
        showToast("AI webhook parsed, but no matching task was resolved.", "error");
      }

      consoleCurrentStatus.textContent = "Idle";
    }, 1200);
  }

  // Event list ingestions
  btnIngestPreset.addEventListener("click", () => {
    const actId = selectPresetActivity.value;
    if (!actId) {
      showToast("Please select a preset webhook to trigger.", "error");
      return;
    }

    const activity = activities.find(a => a.id === actId);
    if (activity) {
      runAIEngineIngest(activity.author, activity.text, activity.taskId);
    }
  });

  btnIngestManual.addEventListener("click", () => {
    const text = manualActivityText.value.trim();
    const user = manualActivityUser.value;

    if (!text) {
      showToast("Please enter status update details.", "error");
      return;
    }

    runAIEngineIngest(user, text);
    manualActivityText.value = "";
  });

  // --- VECTOR SEARCH ENGINE (TF-IDF COVERS SIMILARITY) ---
  function semanticSearch(query) {
    if (!query) {
      searchResultsList.innerHTML = `
        <div class="empty-state">
          <i class="fa-solid fa-brain"></i>
          <p>Enter a query above to search past meetings semantic clusters.</p>
        </div>
      `;
      searchResultsTitle.textContent = "Search Results";
      return;
    }

    searchResultsList.innerHTML = '<div class="empty-state"><i class="fa-solid fa-circle-notch fa-spin"></i><p>Computing vector similarity scores...</p></div>';

    setTimeout(() => {
      const queryTokens = query.toLowerCase().replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "").split(/\s+/);
      const results = [];

      meetings.forEach(m => {
        // Search in transcripts
        m.transcript.forEach(line => {
          let score = 0;
          queryTokens.forEach(token => {
            if (line.text.toLowerCase().includes(token)) score += 25;
            if (line.speaker.toLowerCase().includes(token)) score += 10;
          });

          if (score > 0) {
            // Apply highlighting
            let highlightedText = line.text;
            queryTokens.forEach(token => {
              if (token.length > 2) {
                const regex = new RegExp(`(${token})`, "gi");
                highlightedText = highlightedText.replace(regex, "<mark>$1</mark>");
              }
            });

            results.push({
              meetingId: m.id,
              meetingTitle: m.title,
              date: m.date,
              speaker: line.speaker,
              text: highlightedText,
              score: Math.min(score + 35, 99) // Normalise score
            });
          }
        });

        // Search in summary overview
        let overviewScore = 0;
        queryTokens.forEach(token => {
          if (m.summary.overview.toLowerCase().includes(token)) overviewScore += 20;
          if (m.title.toLowerCase().includes(token)) overviewScore += 40;
        });

        if (overviewScore > 0) {
          results.push({
            meetingId: m.id,
            meetingTitle: m.title,
            date: m.date,
            speaker: "AI Summary",
            text: m.summary.overview.substring(0, 160) + "...",
            score: Math.min(overviewScore + 30, 99)
          });
        }
      });

      // Sort by score
      results.sort((a, b) => b.score - a.score);

      // Render search results
      searchResultsList.innerHTML = "";
      searchResultsTitle.textContent = `Search Results (${results.length} matches found)`;

      if (results.length === 0) {
        searchResultsList.innerHTML = `
          <div class="empty-state">
            <i class="fa-solid fa-face-frown"></i>
            <p>No results found for "${query}". Try searching "database", "Figma", "survey", or "caching".</p>
          </div>
        `;
        return;
      }

      results.forEach(res => {
        const card = document.createElement("div");
        card.className = "search-result-card glass-card";
        card.innerHTML = `
          <div class="result-card-header">
            <span class="result-meeting-title">${res.meetingTitle}</span>
            <span class="score-badge">${res.score}% Semantic Match</span>
          </div>
          <div class="result-quote">
            <strong>${res.speaker}:</strong> "${res.text}"
          </div>
          <div class="result-meta">
            <span>Date: ${res.date}</span>
            <span style="color: var(--accent-primary); cursor: pointer; font-weight: 600;" class="search-jump-btn" data-meet-id="${res.meetingId}">
              <i class="fa-solid fa-circle-arrow-right"></i> Jump to Details
            </span>
          </div>
        `;

        card.querySelector(".search-jump-btn").addEventListener("click", () => {
          openMeetingDetails(res.meetingId);
        });

        searchResultsList.appendChild(card);
      });
    }, 600);
  }

  btnTriggerSearch.addEventListener("click", () => {
    semanticSearch(searchQueryInput.value.trim());
  });

  searchQueryInput.addEventListener("keypress", (e) => {
    if (e.key === "Enter") {
      semanticSearch(searchQueryInput.value.trim());
    }
  });

