  // --- MEETINGS HUB: EDIT & ADD & DELETE OPERATIONS ---

  // --- MEETING DETAIL: CALENDAR (FULL DATES) & EDIT HISTORY ---
  async function renderDetailCalendar(meet) {
    const daysGrid = document.getElementById("detail-calendar-days");
    const eventsEl = document.getElementById("detail-calendar-events");
    const monthLabel = document.getElementById("detail-cal-month");
    const prevBtn = document.getElementById("detail-cal-prev");
    const nextBtn = document.getElementById("detail-cal-next");

    if (!daysGrid || !eventsEl || !monthLabel) return;

    // Default: show month of the meeting's date
    const baseDate = new Date(meet?.date || new Date().toLocaleDateString("en-US"));
    if (Number.isNaN(baseDate.getTime())) {
      // fallback
      baseDate.setFullYear(2026, 5, 22);
    }

    if (!renderDetailCalendar._state) {
      renderDetailCalendar._state = { year: baseDate.getFullYear(), month: baseDate.getMonth() };
    } else {
      renderDetailCalendar._state.year = baseDate.getFullYear();
      renderDetailCalendar._state.month = baseDate.getMonth();
    }

    const state = renderDetailCalendar._state;
    const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];

    function renderMonth() {
      const { year, month } = state;
      monthLabel.textContent = `${monthNames[month]} ${year}`;
      daysGrid.innerHTML = "";
      eventsEl.innerHTML = "";

      // Collect ONLY the selected meeting's deadlines (not workspace-wide)
      const deadlineItems = [];
      (meet?.actionItems || []).forEach(t => {
        if (t.deadline) deadlineItems.push({ meeting: meet, task: t, deadline: t.deadline });
      });


      const monthStart = new Date(year, month, 1);
      const monthEnd = new Date(year, month + 1, 0);
      const firstDayIndex = monthStart.getDay();

      // leading empties
      for (let i = 0; i < firstDayIndex; i++) {
        const empty = document.createElement("div");
        empty.className = "calendar-day-cell empty-cell";
        daysGrid.appendChild(empty);
      }

      // Month day cells
      const today = new Date();
      for (let d = 1; d <= monthEnd.getDate(); d++) {
        const cellDate = new Date(year, month, d);
        const dateStr = `${cellDate.getFullYear()}-${(cellDate.getMonth()+1).toString().padStart(2,"0")}-${cellDate.getDate().toString().padStart(2,"0")}`;

        const cell = document.createElement("div");
        cell.className = "calendar-day-cell";
        cell.textContent = d;

        // Full dates are visible via tooltip/title and event list
        if (cellDate.toDateString() === today.toDateString()) cell.classList.add("today");

        // mark if this day has deadlines/meetings
        const due = deadlineItems.filter(x => x.deadline === dateStr);
        // Show ONLY the selected meeting's date in the calendar
        const uploads = (function(){
          if (!meet?.date) return [];
          try {
            const mDate = new Date(meet.date);
            const mStr = `${mDate.getFullYear()}-${(mDate.getMonth()+1).toString().padStart(2,"0")}-${mDate.getDate().toString().padStart(2,"0")}`;
            return mStr === dateStr ? [meet] : [];
          } catch { return []; }
        })();


        if (due.length > 0) cell.classList.add("has-deadline");
        if (uploads.length > 0) cell.classList.add("has-meeting");

        cell.title = due.length || uploads.length ? `Full date: ${cellDate.toDateString()}` : `Full date: ${cellDate.toDateString()}`;

        cell.addEventListener("click", () => {
          daysGrid.querySelectorAll(".calendar-day-cell.selected").forEach(x => x.classList.remove("selected"));
          cell.classList.add("selected");

          // Render event list (full dates)
          const header = `${cellDate.toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}`;
          const parts = [];

          if (uploads.length) {
            const ul = uploads.map(m => `<div><i class="fa-solid fa-microphone" style="color: var(--accent-primary); margin-right:0.35rem;"></i>${m.title}</div>`).join("");
            parts.push(`<div style="margin-bottom:0.75rem;"><div style="font-weight:700;color:var(--text-primary);">Meetings</div>${ul}</div>`);
          }

          if (due.length) {
            const dl = due.map(x => {
              const prBadge = x.task.priority === "High" ? "badge-high" : x.task.priority === "Medium" ? "badge-medium" : "badge-low";
              return `<div style="display:flex;justify-content:space-between;gap:0.75rem;align-items:center; padding:0.45rem 0.6rem; border:1px solid var(--card-border); border-radius:10px; background:rgba(255,255,255,0.02); margin-bottom:0.4rem;">
                <div style="min-width:0;">
                  <div style="font-weight:600;color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${x.task.title}</div>
                  <div style="font-size:0.75rem;color:var(--text-muted);">From: <strong style="color:var(--accent-primary);">${x.meeting.title}</strong></div>
                </div>
                <span class="badge ${prBadge}">${x.task.status === "Completed" ? "Completed" : x.task.priority}</span>
              </div>`;
            }).join("");
            parts.push(`<div><div style="font-weight:700;color:var(--text-primary);">Deadlines</div>${dl}</div>`);
          }

          if (!parts.length) {
            eventsEl.innerHTML = `<div class="empty-state" style="padding:1rem;color:var(--text-muted);"><i class="fa-solid fa-inbox" style="font-size:1.4rem;opacity:0.4;display:block;"></i><div style="font-weight:700;color:var(--text-primary); margin-bottom:0.25rem;">${header}</div><div style="font-size:0.8rem;">No deadlines or meetings scheduled.</div></div>`;
          } else {
            eventsEl.innerHTML = `<div style="margin-bottom:0.75rem;"><div style="font-weight:800;color:var(--text-primary);">${header}</div><div style="font-size:0.8rem;color:var(--text-muted);">Full dates shown</div></div>${parts.join("")}`;
          }
        });

        daysGrid.appendChild(cell);
      }

      // Auto select meeting's date if in this month
      const meetDate = new Date(meet?.date);
      if (!Number.isNaN(meetDate.getTime()) && meetDate.getFullYear() === year && meetDate.getMonth() === month) {
        const targetDay = meetDate.getDate();
        const cell = Array.from(daysGrid.children).find(c => c.textContent === String(targetDay));
        if (cell) cell.click();
      }
    }

    renderMonth();

    if (prevBtn) prevBtn.onclick = () => { state.month--; if (state.month < 0) { state.month = 11; state.year--; } renderMonth(); };
    if (nextBtn) nextBtn.onclick = () => { state.month++; if (state.month > 11) { state.month = 0; state.year++; } renderMonth(); };
  }

  // --- CONTACT PAGE RATING ---
  function initContactRating() {
    const starBtns = document.querySelectorAll("#contact-star-row .contact-star-btn");
    const label = document.getElementById("contact-rating-label");
    const tagsContainer = document.getElementById("contact-rating-tags");
    if (!starBtns.length || !label) return;

    const saved = parseInt(localStorage.getItem("echoaction_app_rating") || "0", 10);
    const savedTags = JSON.parse(localStorage.getItem("echoaction_app_tags") || "[]");
    let current = saved;

    const labels = ["", "Terrible", "Poor", "Average", "Good", "Excellent"];
    const colors = ["", "#f43f5e", "#f97316", "#eab308", "#22c55e", "#06b6d4"];

    function paint(n) {
      starBtns.forEach(btn => {
        const s = parseInt(btn.getAttribute("data-star"));
        btn.style.color = s <= n ? "#f59e0b" : "var(--text-muted)";
        btn.style.transform = s <= n ? "scale(1.15)" : "scale(1)";
      });
    }

    function showLabel(n) {
      if (n > 0) {
        label.textContent = `${labels[n]} (${n}/5)`;
        label.style.color = colors[n];
      } else {
        label.textContent = "Tap a star to rate";
        label.style.color = "var(--text-muted)";
      }
    }

    function showTags(n) {
      if (tagsContainer) tagsContainer.style.display = n > 0 ? "flex" : "none";
    }

    function paintTags() {
      document.querySelectorAll(".contact-tag-btn").forEach(btn => {
        const t = btn.getAttribute("data-tag");
        if (savedTags.includes(t)) {
          btn.style.background = "rgba(245,158,11,0.15)";
          btn.style.color = "#f59e0b";
          btn.style.borderColor = "#f59e0b";
        } else {
          btn.style.background = "transparent";
          btn.style.color = "var(--text-muted)";
          btn.style.borderColor = "var(--card-border)";
        }
      });
    }

    paint(current);
    showLabel(current);
    showTags(current);
    paintTags();

    starBtns.forEach(btn => {
      btn.onmouseenter = () => {
        const n = parseInt(btn.getAttribute("data-star"));
        starBtns.forEach(b => { b.style.color = parseInt(b.getAttribute("data-star")) <= n ? "#fbbf24" : "var(--text-muted)"; });
      };
      btn.onmouseleave = () => { paint(current); };
      btn.onclick = () => {
        current = parseInt(btn.getAttribute("data-star"));
        paint(current);
        showLabel(current);
        showTags(current);
        localStorage.setItem("echoaction_app_rating", current);
        showToast(`Thanks! You rated EchoAction ${current}/5 stars.`);
      };
    });

    document.querySelectorAll(".contact-tag-btn").forEach(btn => {
      btn.onclick = () => {
        const tag = btn.getAttribute("data-tag");
        const idx = savedTags.indexOf(tag);
        if (idx >= 0) { savedTags.splice(idx, 1); } else { savedTags.push(tag); }
        localStorage.setItem("echoaction_app_tags", JSON.stringify(savedTags));
        paintTags();
        if (savedTags.length > 0) showToast("Feedback tag saved!");
      };
      btn.onmouseenter = () => { if (!savedTags.includes(btn.getAttribute("data-tag"))) { btn.style.borderColor = "rgba(245,158,11,0.4)"; btn.style.color = "var(--text-primary)"; } };
      btn.onmouseleave = () => { if (!savedTags.includes(btn.getAttribute("data-tag"))) { btn.style.borderColor = "var(--card-border)"; btn.style.color = "var(--text-muted)"; } };
    });
  }

  function getVal(item, keys, def) {
    for (let k of keys) { let v = item[k]; if (v != null && v !== "") return v; }
    return def || "";
  }

  function formatValue(s) {
    if (!s || s === "" || s === "None") return "";
    // Try to parse JSON and show human-readable
    try {
      const o = JSON.parse(s);
      if (o !== null && typeof o === "object" && !Array.isArray(o)) {
        return Object.entries(o).map(([k,v]) => k.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase()) + ": " + v).join("\n");
      }
      if (Array.isArray(o)) return o.join(", ");
      return String(o);
    } catch(e) {}
    // Clean up Python string representations: [{'a':'b'}] -> readable
    let t = String(s);
    t = t.replace(/'/g, '"');
    try { const o = JSON.parse(t); return formatValue(JSON.stringify(o)); } catch(e2) {}
    t = t.replace(/\\n/g, '\n');
    return t;
  }

  function showEditDetailModal(item, meet) {
    const overlay = document.createElement("div");
    overlay.style.cssText = "position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.6);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;";
    overlay.addEventListener("click", (e) => { if (e.target === overlay) overlay.remove(); });

    const card = document.createElement("div");
    card.style.cssText = "background:var(--bg-secondary);border:1px solid var(--card-border);border-radius:16px;max-width:600px;width:90%;max-height:80vh;overflow-y:auto;box-shadow:0 25px 50px -12px rgba(0,0,0,0.5);";

    const field = getVal(item,["field","field_changed","type"]);
    const editor = getVal(item,["editorEmail","email","editedBy","user"]);
    const when = getVal(item,["createdAt","timestamp","editedAt","created_at"]);
    const oldVal = formatValue(getVal(item,["oldValue","old_value"]));
    const newVal = formatValue(getVal(item,["newValue","new_value"]));
    const desc = item.description || "";

    const esc = (s) => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

    let rows = '';
    if (desc) rows += '<div style="color:var(--text-muted);font-weight:600;">Action</div><div style="color:var(--text-primary);">' + esc(desc) + '</div>';
    rows += '<div style="color:var(--text-muted);font-weight:600;">Editor</div><div style="color:var(--text-primary);">' + esc(editor) + '</div>';
    rows += '<div style="color:var(--text-muted);font-weight:600;">Field</div><div style="color:var(--text-primary);">' + esc(field) + '</div>';
    rows += '<div style="color:var(--text-muted);font-weight:600;">When</div><div style="color:var(--text-primary);font-family:monospace;">' + esc(when) + '</div>';
    if (oldVal) rows += '<div style="color:var(--text-muted);font-weight:600;">Old Value</div><div style="color:var(--text-secondary);background:rgba(244,63,94,0.05);padding:0.5rem 0.75rem;border-radius:8px;border:1px solid rgba(244,63,94,0.15);white-space:pre-wrap;word-break:break-word;max-height:200px;overflow-y:auto;">' + esc(oldVal) + '</div>';
    if (newVal) rows += '<div style="color:var(--text-muted);font-weight:600;">New Value</div><div style="color:var(--text-primary);background:rgba(16,185,129,0.05);padding:0.5rem 0.75rem;border-radius:8px;border:1px solid rgba(16,185,129,0.15);white-space:pre-wrap;word-break:break-word;max-height:200px;overflow-y:auto;">' + esc(newVal) + '</div>';

    card.innerHTML = '<div style="padding:1.25rem 1.5rem;border-bottom:1px solid var(--card-border);display:flex;justify-content:space-between;align-items:center;"><div style="font-size:1rem;font-weight:700;color:var(--text-primary);"><i class="fa-solid fa-pen-to-square" style="color:var(--accent-primary);margin-right:0.5rem;"></i>Edit Details</div><button id="edit-detail-close" aria-label="Close edit details" style="background:none;border:none;color:var(--text-muted);font-size:1.2rem;cursor:pointer;padding:0.25rem;"><i class="fa-solid fa-xmark"></i></button></div><div style="padding:1.5rem;display:flex;flex-direction:column;gap:1rem;"><div style="display:grid;grid-template-columns:100px 1fr;gap:0.5rem;font-size:0.88rem;">' + rows + '</div>' + (meet ? '<div style="border-top:1px solid var(--card-border);padding-top:1rem;font-size:0.8rem;color:var(--text-muted);">Meeting: <strong style="color:var(--text-primary);">' + esc(meet.title) + '</strong> (ID: ' + esc(meet.id) + ')</div>' : '') + '</div>';

    overlay.appendChild(card);
    document.body.appendChild(overlay);

    card.querySelector("#edit-detail-close").onclick = () => overlay.remove();

    const escHandler = (e) => { if (e.key === "Escape") { overlay.remove(); document.removeEventListener("keydown", escHandler); } };
    document.addEventListener("keydown", escHandler);
  }


  function deleteMeeting(meetingId) {
    const mTitle = (meetings.find(m => m.id === meetingId) || {}).title || "Unknown";
    meetings = meetings.filter(m => m.id !== meetingId);
    saveMeetingsToStorage();
    logEdit("meeting_delete", `Deleted meeting "${mTitle}"`);
    showToast("Meeting deleted successfully.", "success");
    renderMeetingsHub();
    renderDashboardStats();
    renderDemoPicker();
    if (currentActiveMeeting && currentActiveMeeting.id === meetingId) {
      currentActiveMeeting = null;
      meetingsListContainer.style.display = "block";
      meetingDetailContainer.style.display = "none";
    }
  }

