    btnDeleteActiveMeeting.addEventListener("click", () => {
      if (currentActiveMeeting) {
        if (confirm(`Are you sure you want to delete "${currentActiveMeeting.title}"?`)) {
          deleteMeeting(currentActiveMeeting.id);
        }
      }
    });
