  function openAddMeetingModal(mode) {
    addMeetingModal.classList.add("active");
    document.getElementById("new-meet-title").value = "";
    document.getElementById("new-meet-category").value = "";
    document.getElementById("new-meet-overview").value = "";
    document.getElementById("new-meet-main-points").value = "";
    document.getElementById("new-meet-important-dates").value = "";
    document.getElementById("new-meet-date").value = new Date().toISOString().split('T')[0];
    
    const classFields = document.getElementById("class-mode-fields");
    if (mode === "class") {
      document.getElementById("new-meet-category").placeholder = "e.g., Lecture, Tutorial, Workshop";
      classFields.style.display = "flex";
    } else {
      document.getElementById("new-meet-category").placeholder = "e.g., Project Sync, Team Meeting";
      classFields.style.display = "none";
    }
  }

  if (btnAddMeetCancel) {
    btnAddMeetCancel.addEventListener("click", () => {
      addMeetingModal.classList.remove("active");
    });
  }

  if (btnAddMeetSubmit) {
    btnAddMeetSubmit.addEventListener("click", () => {
      const title = document.getElementById("new-meet-title").value.trim();
      const category = document.getElementById("new-meet-category").value.trim();
      const dateVal = document.getElementById("new-meet-date").value;
      const overview = document.getElementById("new-meet-overview").value.trim();
      const mainPoints = document.getElementById("new-meet-main-points").value.trim();
      const importantDates = document.getElementById("new-meet-important-dates").value.trim();

      if (!title || !category || !overview) {
        showToast("Please fill out Title, Category, and Overview fields.", "error");
        return;
      }

      // Fix timezone: parse date parts directly from the input value (YYYY-MM-DD)
      let formattedDate;
      if (dateVal) {
        const parts = dateVal.split("-");
        const yr = parseInt(parts[0]), mo = parseInt(parts[1]) - 1, dy = parseInt(parts[2]);
        formattedDate = new Date(yr, mo, dy).toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
      } else {
        formattedDate = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
      }
      const newMeet = {
        id: "meet-rand-" + Date.now(),
        status: "Previous",
        title: title,
        category: category,
        date: formattedDate,
        duration: "15m 00s",
        attendees: ["Sarah Jenkins"],
        audioUrl: "#",
        summary: {
          overview: overview,
          keyPoints: ["Manual entry created by user."],
          sentiment: "Neutral",
          meetingScore: 85
        },
        actionItems: [],
        jiraTickets: [],
        emailDraft: {
          subject: "Meeting Summary: " + title,
          body: `Hi Team,\n\nHere is the summary of the meeting:\n\n- ${overview}\n\nBest,\nEchoAction AI`
        },
        transcript: [
          { speaker: "Sarah Jenkins", time: "00:00", text: "Meeting manually created." }
        ]
      };

      if (category === "Lecture Sync") {
        // Parse main points into array
        const mainPointsArray = mainPoints
          .split('\n')
          .map(point => point.trim())
          .filter(point => point.length > 0);

        newMeet.class_notes = {
          lecture_notes: overview,
          main_points: mainPointsArray.length > 0 ? mainPointsArray : ["No main points provided"],
          important_dates: importantDates || "No important dates specified",
          concepts: [
            { term: "First Concept Name", definition: "Example concept description defined manually." }
          ],
          study_guide: [
            "Example study tip to remember."
          ],
          qa: [
            { question: "Example Question?", answer: "Example Answer." }
          ],
          assignments: []
        };
      }

      meetings.push(newMeet);
      saveMeetingsToStorage();
      logEdit("meeting_add", `Created meeting "${newMeet.title}"`);
      addMeetingModal.classList.remove("active");
      showToast("Manual meeting created successfully!", "success");
      renderMeetingsHub();
      renderDashboardStats();
      renderDemoPicker();
      openMeetingDetails(newMeet.id);
    });
  }

