  // ─── PER-MEETING EDIT HISTORY ──────────────────────────────────────────────
  function renderMeetingEditHistory(meet) {
    const listEl = document.getElementById("edit-history-list");
    if (!listEl) return;
    listEl.innerHTML = '<div style="padding:1rem;color:var(--text-muted);text-align:center;"><i class="fa-solid fa-clock-rotate-left" style="opacity:0.5;margin-right:0.5rem;"></i>Loading...</div>';
    const meetingId = meet && meet.id;
    if (!meetingId) { listEl.innerHTML = '<div style="padding:2rem;text-align:center;color:var(--text-muted);">No meeting selected.</div>'; return; }
    // Only fetch from DB — localStorage is not merged to avoid duplicates (timestamps differ)
    fetch("/api/edit-history?meetingId=" + encodeURIComponent(meetingId)).then(r => r.json()).then(data => { renderTable((data && data.history) ? data.history : (data && data.edits) ? data.edits : []); }).catch(() => renderTable([]));
    function renderTable(items) {
      if (!items || items.length === 0) { listEl.innerHTML = '<div style="padding:2rem;text-align:center;color:var(--text-muted);"><i class="fa-solid fa-clipboard" style="font-size:1.6rem;display:block;opacity:0.4;margin-bottom:0.5rem;"></i><div style="font-weight:700;color:var(--text-primary);margin-bottom:0.25rem;">No edits yet</div><div style="font-size:0.85rem;">Changes to this meeting will appear here.</div></div>'; return; }
      listEl.innerHTML = '<table class="task-table" style="margin-top:0;"><thead><tr><th style="min-width:100px;">Editor</th><th style="min-width:90px;">Field</th><th>Change</th><th style="width:130px;">When</th><th style="width:60px;"></th></tr></thead><tbody></tbody></table>';
      const tbody = listEl.querySelector("tbody");
      items.forEach(item => {
        const desc = item.description || "";
        const oldV = getVal(item,["oldValue","old_value"]);
        const newV = getVal(item,["newValue","new_value"]);
        let changeText = desc;
        if (!changeText && oldV && newV) changeText = oldV + ' \u2192 ' + newV;
        if (!changeText) changeText = getVal(item,["field","field_changed","type"]);
        const tr = document.createElement("tr");
        tr.style.cursor = "pointer";
        tr.innerHTML = '<td>' + escHtml(getVal(item,["editorEmail","email","editedBy","user"])) + '</td><td style="font-weight:600;color:var(--accent-primary);">' + escHtml(getVal(item,["field","field_changed","type"])) + '</td><td style="color:var(--text-primary);font-size:0.85rem;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + escHtml(changeText) + '">' + escHtml(changeText) + '</td><td style="font-family:monospace;color:var(--text-muted);font-size:0.8rem;">' + escHtml(getVal(item,["createdAt","timestamp","editedAt","created_at"])) + '</td><td style="text-align:center;"><button class="btn btn-secondary details-btn" style="padding:0.2rem 0.5rem;font-size:0.7rem;cursor:pointer;">More details</button></td>';
        tr.addEventListener("click", function(e) { if (e.target.closest(".details-btn")) return; showEditDetailModal(item, meet); });
        var detailsBtn = tr.querySelector(".details-btn"); if (detailsBtn) detailsBtn.addEventListener("click", function(e) { e.stopPropagation(); showEditDetailModal(item, meet); });
        tbody.appendChild(tr);
      });
    }
    function escHtml(s) { return String(s || "").replace(/[&<>"]/g, function(c) { return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
  }

  // --- BACKEND DATA INTEGRATION ---
  // Reads Flask-injected JSON from the #backend-data <script> tag in index.html.
  // Called once at startup. If a server-side transcription was successful (POST),
  // it builds a meeting object from the results and adds it to the meetings list.
  function checkPreloadedBackendData() {
    const dataEl = document.getElementById("backend-data");
    if (!dataEl) return;

    let data;
    try {
      data = JSON.parse(dataEl.textContent);
    } catch (e) {
      console.warn("EchoAction: Could not parse backend-data JSON:", e);
      return;
    }

    if (!data) return;

    // Show any backend error as a toast
    if (data.error) {
      showToast(`Server Error: ${data.error}`, "error");
      return;
    }

    // If Flask successfully processed an upload, create a meeting from the result
    if (data.success && data.transcript) {
      const transcript = data.transcript || "";
      const summary = data.summary || "";
      const actions = data.actions || [];
      const deadlines = data.deadlines || [];
      const mode = data.mode || "meeting";
      const filename = data.filename || "Uploaded File";
      const classNotes = data.class_notes || null;

      // Build action items from backend-extracted actions
      const actionItems = actions.map((a, idx) => {
        const tm = resolveTeamMember(a.assignee || "Sarah Jenkins");
        return {
          id: `task-backend-${Date.now()}-${idx}`,
          title: a.title || a,
          assignee: tm.name,
          avatar: tm.avatar,
          priority: a.priority || "Medium",
          deadline: a.deadline || (deadlines[0] || new Date(Date.now() + 86400000 * 3).toISOString().split("T")[0]),
          status: "Pending",
          category: "General",
          matchKeywords: [String(a.title || a).split(" ")[0].toLowerCase()]
        };
      });

      // Build a basic Jira ticket for each high-priority action
      const jiraTickets = actionItems
        .filter(a => a.priority === "High")
        .map((a, idx) => ({
          id: `JIRA-BE-${100 + idx}`,
          title: a.title,
          type: "Task",
          priority: a.priority,
          assignee: a.assignee,
          description: `Auto-generated from uploaded file: ${filename}`
        }));

      // Build transcript lines
      const transcriptLines = transcript
        .split(/[.\n]/)
        .filter(t => t.trim())
        .slice(0, 30)
        .map((line, i) => ({
          speaker: "Speaker",
          time: `${Math.floor(i * 8 / 60).toString().padStart(2, "0")}:${((i * 8) % 60).toString().padStart(2, "0")}`,
          text: line.trim()
        }));

      // Build lecture notes for class mode
      let lectureNotesObj = null;
      if (mode === "class" && classNotes) {
        lectureNotesObj = {
          content: classNotes.lecture_notes || "",
          concepts: (classNotes.concepts || []).map((c, i) => ({ id: `concept-be-${i}`, term: c.split(":")[0] || c, definition: c })),
          studyTips: classNotes.study_guide || [],
          qa: classNotes.qa || [],
          transcript: transcriptLines
        };
      }

      const meetingId = `meet-backend-${Date.now()}`;
      const isVideoUpload = filename && /\.(mp4|mkv|mov|avi|webm|flv|wmv|m4v|mpeg|mpg)$/i.test(filename);
      const newMeeting = {
        id: meetingId,
        title: filename.replace(/\.[^.]+$/, "") || "Uploaded Meeting",
        category: mode === "class" ? "Class Lecture" : "Backend Sync",
        date: new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" }),
        duration: "Auto",
        status: "Previous",
        mode: mode,
        modeType: isVideoUpload ? "video" : "audio",
        fileType: isVideoUpload ? "video" : "audio",
        attendees: ["Sarah Jenkins"],
        audioUrl: null,
        summary: {
          overview: summary || transcript.slice(0, 300),
          keyPoints: actions.slice(0, 5).map(a => (typeof a === "string" ? a : a.title)),
          sentiment: "Processed via local Whisper backend",
          meetingScore: 80
        },
        actionItems,
        jiraTickets,
        emailDraft: {
          subject: `EchoAction Summary: ${filename}`,
          body: `Hi Team,\n\nHere is a summary of the uploaded file "${filename}":\n\n${summary}\n\nBest,\nEchoAction AI`
        },
        transcript: transcriptLines,
        classNotes: lectureNotesObj,
        deadlines
      };

      // Only add if the user is already authenticated (meetings array is populated)
      // Otherwise, store it temporarily and add after login
      if (currentUser) {
        meetings.push(newMeeting);
        saveMeetingsToStorage();
        renderDashboardStats();
        renderDemoPicker();
        showToast(`File "${filename}" processed successfully!`);
      } else {
        // Queue it — add after successful login via applyUserSession
        window._pendingBackendMeeting = newMeeting;
      }
    }
  }

