  function renderProfileLinks() {
    const container = document.getElementById("profile-links-list");
    if (!container) return;
    container.innerHTML = "";
    if (profileLinks.length === 0) {
      container.innerHTML = '<div style="text-align:center;padding:0.75rem;font-size:0.8rem;color:var(--text-muted);"><i class="fa-solid fa-link-slash" style="margin-right:0.3rem;"></i>No links added yet.</div>';
      return;
    }
    profileLinks.forEach((link, idx) => {
      const row = document.createElement("div");
      row.style.cssText = "display:flex;align-items:center;gap:0.5rem;padding:0.5rem 0.75rem;background:rgba(255,255,255,0.02);border:1px solid var(--card-border);border-radius:8px;";
      row.innerHTML = '<i class="fa-solid fa-up-right-from-square" style="color:var(--accent-primary);font-size:0.8rem;"></i><a href="' + link.url + '" target="_blank" style="flex:1;font-size:0.85rem;color:var(--accent-primary);text-decoration:none;font-weight:500;">' + link.label + '</a><button class="btn-del-link" data-idx="' + idx + '" style="background:none;border:none;color:var(--danger);cursor:pointer;font-size:0.85rem;padding:0.15rem 0.35rem;" title="Remove link"><i class="fa-solid fa-xmark"></i></button>';
      container.appendChild(row);
    });
    container.querySelectorAll(".btn-del-link").forEach(btn => {
      btn.addEventListener("click", () => {
        const idx = parseInt(btn.dataset.idx);
        profileLinks.splice(idx, 1);
        localStorage.setItem("echoaction_profile_links", JSON.stringify(profileLinks));
        if (currentUser) _dbSyncProfileLinks(profileLinks);
        renderProfileLinks();
        showToast("Link removed.");
      });
    });
  }

