  // --- OFFICE HOURS REAL-TIME STATUS ---
  function updateOfficeHoursStatus() {
    const el = document.getElementById("office-hours-status");
    if (!el) return;
    // Use IST (UTC+5:30)
    const now = new Date();
    const istOffset = 5.5 * 60 * 60 * 1000;
    const ist = new Date(now.getTime() + istOffset - (now.getTimezoneOffset() * 60 * 1000));
    const dayOfWeek = ist.getDay(); // 0=Sun, 1=Mon,..., 6=Sat
    const hour = ist.getHours();
    const minute = ist.getMinutes();
    const timeDecimal = hour + minute / 60;

    let isOpen = false;
    let statusMsg = "";
    if (dayOfWeek >= 1 && dayOfWeek <= 5) {
      // Mon-Fri: 9AM - 6PM
      isOpen = timeDecimal >= 9 && timeDecimal < 18;
      statusMsg = isOpen
        ? "🟢 Open Now (Mon–Fri 9 AM – 6 PM IST)"
        : (timeDecimal < 9
            ? `⏰ Opens today at 9:00 AM IST`
            : "🔴 Closed for today. Opens Monday 9 AM IST");
    } else if (dayOfWeek === 6) {
      // Saturday: 9AM - 1PM
      isOpen = timeDecimal >= 9 && timeDecimal < 13;
      statusMsg = isOpen
        ? "🟢 Open Now (Saturday 9 AM – 1 PM IST)"
        : (timeDecimal < 9
            ? "⏰ Opens today at 9:00 AM IST"
            : "🔴 Closed for today. Opens Monday 9 AM IST");
    } else {
      // Sunday
      statusMsg = "🔴 Closed (Sunday). Opens Monday 9 AM IST";
    }
    el.textContent = statusMsg;
    el.style.color = isOpen ? "var(--success)" : "var(--danger)";
  }
  updateOfficeHoursStatus();
  setInterval(updateOfficeHoursStatus, 60000); // Update every minute

