      links.forEach(l => { html += '<a href="'+esc(l.url)+'" target="_blank" style="font-size:0.78rem;color:#10b981;text-decoration:none;padding:0.2rem 0.35rem;background:rgba(255,255,255,0.02);border-radius:4px;"><i class="fa-solid fa-up-right-from-square" style="font-size:0.6rem;margin-right:0.3rem;"></i>'+esc(l.label)+'</a>'; });
      html += '</div></div>';
