          const fb = cd.querySelector(".std-social-follow-btn"); if(fb&&!ia&&!ir)fb.onclick=function(e){e.stopPropagation();var r2=JSON.parse(localStorage.getItem("echoaction_followreqs_"+currentUser.email)||"[]");if(r2.indexOf(u.email)<0){r2.push(u.email);localStorage.setItem("echoaction_followreqs_"+currentUser.email,JSON.stringify(r2));showToast("Follow request sent!","success");stdRenderDiscover(document.getElementById("std-discover-user-search")?.value||"");stdRenderReqList();}};
          const mb = cd.querySelector(".std-social-msg-btn"); if(mb)mb.onclick=function(e){e.stopPropagation();if(typeof openMessengerToUser==="function")openMessengerToUser(u);else showToast("Messenger not available","info");};
          const db = cd.querySelector(".std-social-del-btn"); if(db)db.onclick=function(e){e.stopPropagation();var a2=JSON.parse(localStorage.getItem("echoaction_followers_accepted_"+currentUser.email)||"[]");var ix=a2.indexOf(u.email);if(ix>=0){a2.splice(ix,1);localStorage.setItem("echoaction_followers_accepted_"+currentUser.email,JSON.stringify(a2));stdRenderDiscover(document.getElementById("std-discover-user-search")?.value||"");stdRenderFolList();}};
