          const cd=document.createElement("div"); cd.style.cssText="display:flex;align-items:center;gap:0.65rem;padding:0.6rem 0.75rem;border-radius:10px;border:1px solid rgba(255,255,255,0.08);";
          cd.innerHTML='<div style="width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,#818cf8,rgba(99,102,241,0.7));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:0.8rem;flex-shrink:0;">'+init+'</div><div style="flex:1;"><div style="font-size:0.82rem;font-weight:600;color:#e8edf5;">'+(u.name||"Unknown")+'</div><div style="font-size:0.7rem;color:#8899b0;">'+(u.email||"")+'</div></div><div style="display:flex;gap:0.35rem;"><button class="std-req-accept-btn" style="padding:0.35rem 0.55rem;border-radius:6px;border:1px solid #10b981;background:rgba(16,185,129,0.08);color:#10b981;font-size:0.72rem;cursor:pointer;"><i class="fa-solid fa-check"></i> Accept</button><button class="std-req-delete-btn" style="padding:0.35rem 0.55rem;border-radius:6px;border:1px solid #ef4444;background:rgba(239,68,68,0.08);color:#ef4444;font-size:0.72rem;cursor:pointer;"><i class="fa-solid fa-ban"></i> Delete</button></div>';
          cd.querySelector(".std-req-accept-btn").onclick=function(){var r2=JSON.parse(localStorage.getItem("echoaction_followreqs_"+currentUser.email)||"[]");var ix=r2.indexOf(u.email);if(ix>=0){r2.splice(ix,1);localStorage.setItem("echoaction_followreqs_"+currentUser.email,JSON.stringify(r2));var a2=JSON.parse(localStorage.getItem("echoaction_followers_accepted_"+currentUser.email)||"[]");if(a2.indexOf(u.email)<0)a2.push(u.email);localStorage.setItem("echoaction_followers_accepted_"+currentUser.email,JSON.stringify(a2));stdRenderReqList();stdRenderFolList();stdRenderDiscover(document.getElementById("std-discover-user-search")?.value||"");}};
          cd.querySelector(".std-req-delete-btn").onclick=function(){var r2=JSON.parse(localStorage.getItem("echoaction_followreqs_"+currentUser.email)||"[]");var ix=r2.indexOf(u.email);if(ix>=0){r2.splice(ix,1);localStorage.setItem("echoaction_followreqs_"+currentUser.email,JSON.stringify(r2));stdRenderReqList();stdRenderDiscover(document.getElementById("std-discover-user-search")?.value||"");}};
