      const stdDispNameInput=document.getElementById("std-display-name-input");const stdSaveDispBtn=document.getElementById("std-btn-save-display-name");if(stdSaveDispBtn&&stdDispNameInput){var savedStdDisp=localStorage.getItem("echoaction_std_display_name");if(savedStdDisp)stdDispNameInput.value=savedStdDisp;stdSaveDispBtn.onclick=function(){localStorage.setItem("echoaction_std_display_name",stdDispNameInput.value.trim());showToast("Display name saved!","success");};}
