      +   '<input id="tkt-subject" placeholder="Subject *" style="width:100%;padding:.6rem;margin-bottom:.6rem;border-radius:8px;background:#334155;border:1px solid rgba(255,255,255,.1);color:#f3f4f6;font-size:.8rem;outline:none;box-sizing:border-box;">'
      +   '<textarea id="tkt-desc" placeholder="Description *" style="width:100%;padding:.6rem;margin-bottom:.6rem;border-radius:8px;background:#334155;border:1px solid rgba(255,255,255,.1);color:#f3f4f6;font-size:.8rem;outline:none;min-height:80px;resize:vertical;box-sizing:border-box;"></textarea>'
      +   '<select id="tkt-priority" style="width:100%;padding:.6rem;margin-bottom:.75rem;border-radius:8px;background:#334155;border:1px solid rgba(255,255,255,.1);color:#f3f4f6;font-size:.8rem;outline:none;">'
      +   '<option value="Low">Low</option><option value="Medium" selected>Medium</option><option value="High">High</option><option value="Critical">Critical</option></select>'
