      +   '<div style="margin-top:1rem;"><h4 style="color:#8899b0;font-size:.8rem;margin-bottom:.5rem;">Previous Tickets (' + tickets.length + ')</h4>' + ticketHistoryHtml + '</div>'
      + '</div>'
      + '<div id="ss-faculty" style="display:none;">'
      +   '<h3 style="color:#f3f4f6;font-size:1rem;margin-bottom:1rem;"><i class="fa-solid fa-address-book" style="color:#6366f1;margin-right:.5rem;"></i>Contact Faculty</h3>'
      +   facultyHtml
      + '</div>'
      + '<div id="ss-ai" style="display:none;">'
      +   '<h3 style="color:#f3f4f6;font-size:1rem;margin-bottom:1rem;"><i class="fa-solid fa-robot" style="color:#6366f1;margin-right:.5rem;"></i>AI Assistant</h3>'
      +   '<div id="ss-ai-chat" style="background:#334155;border-radius:10px;padding:.75rem;min-height:120px;max-height:200px;overflow-y:auto;margin-bottom:.6rem;font-size:.78rem;color:#8899b0;"><i>Ask me anything about the platform...</i></div>'
      +   '<div style="display:flex;gap:.5rem;">'
