      +   '<button id="ss-ai-send-btn" style="padding:.5rem 1rem;border-radius:8px;background:linear-gradient(135deg,#6366f1,#818cf8);border:none;color:#fff;font-size:.8rem;cursor:pointer;"><i class="fa-solid fa-paper-plane"></i></button>'
