      +   '<h3 style="color:#f3f4f6;font-size:1rem;margin-bottom:1rem;"><i class="fa-solid fa-circle-question" style="color:#6366f1;margin-right:.5rem;"></i>FAQs</h3>'
      +   faqHtml
      + '</div>'
      + '<div id="ss-tech" style="display:none;">'
