        const profileLink = document.getElementById("partner-profile-link").value.trim();
        const selectedPerms = [];
        document.querySelectorAll(".partner-perm-cb:checked").forEach(cb => selectedPerms.push(cb.dataset.perm));
        const all = JSON.parse(localStorage.getItem("echoaction_meeting_partners")||"{}");
        if (!all[meetingId]) all[meetingId] = [];
        all[meetingId].push({email, company:compVal, role, profileLink, permissions:selectedPerms, addedAt:new Date().toISOString()});
        localStorage.setItem("echoaction_meeting_partners", JSON.stringify(all));
