                  <i class="fa-solid ${r.type === 'Meeting' ? 'fa-people-group' : r.type === 'Project' ? 'fa-cubes' : r.type === 'Productivity' ? 'fa-chart-line' : 'fa-brain'}" style="color:${r.type === 'Meeting' ? '#818cf8' : r.type === 'Project' ? '#10b981' : r.type === 'Productivity' ? '#f59e0b' : '#06b6d4'};font-size:15px;"></i>
