            var typeColors = {meeting_add:'#10b981',meeting_edit:'#818cf8',meeting_delete:'#ef4444',task_add:'#06b6d4',task_edit:'#f59e0b',task_delete:'#ef4444',project_edit:'#818cf8',project_upload:'#10b981',permission_change:'#a78bfa',settings_change:'#6b7a8a',login:'#22d3ee',profile_edit:'#a5b4fc'};
            var icon = typeIcons[entry.type] || 'fa-solid fa-circle';
