              var pUserEmail=(currentUser||{}).email||"me@example.com";
              var pUnifiedMsgs=JSON.parse(localStorage.getItem("echoaction_messages_"+pUserEmail)||"[]");
              pUnifiedMsgs.unshift({id:pMsgId,from:(currentUser||{}).email||"me@example.com",to:(p.name||"Project")+" (Project)",subject:"Project: "+(p.name||""),text:ptxt,timestamp:new Date().toLocaleString(),type:"project",projectId:p.id,projectTitle:p.name,groupId:"project-"+p.id,attachments:[]});
              localStorage.setItem("echoaction_messages_"+pUserEmail,JSON.stringify(pUnifiedMsgs));
