  function genHistory(){var h=function(){try{var hh=JSON.parse(localStorage.getItem("echoaction_edit_history")||"[]");return hh.slice(0,30)}catch(e){return[]}}();var ic={meeting:"fa-video",task:"fa-list-check",settings:"fa-sliders",profile:"fa-user",message:"fa-envelope",project:"fa-diagram-project",deadline:"fa-calendar"};var co={meeting:"#818cf8",task:"#f59e0b",settings:"#a78bfa",profile:"#10b981",message:"#06b6d4",project:"#f97316",deadline:"#ef4444"};return _proCard("clock-rotate-left","#a78bfa","Activity History","Recent activity",h.length?'<div style="display:flex;flex-direction:column;gap:2px;max-height:350px;overflow-y:auto;">'+h.map(function(x){var i=ic[x.type]||"fa-clock",c=co[x.type]||"#6b7a8a";return '<div style="display:flex;align-items:flex-start;gap:6px;padding:5px 6px;background:rgba(255,255,255,0.02);border-radius:5px;font-size:0.72rem;"><i class="fa-solid '+i+'" style="color:'+c+';font-size:0.6rem;margin-top:2px;"></i><div style="flex:1;min-width:0;"><div style="color:#d1d5db;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+esc(x.description||"")+'</div><div style="color:#6b7a8a;font-size:0.62rem;">'+esc(x.timestamp?new Date(x.timestamp).toLocaleString():x.date||"")+'</div></div></div>';}).join("")+'</div>':'<p style="color:#6b7a8a;font-size:0.78rem;text-align:center;">No activity yet.</p>');}
