        if(i>=0&&i<pl.length&&confirm("Delete project?")){var nm=pl[i].name;pl.splice(i,1);localStorage.setItem("echoaction_employee_projects",JSON.stringify(pl));if(typeof logEdit==="function")logEdit("profile","Deleted project: "+nm);renderEmployeeSettings("projects");showToast("Deleted.","info");}
